CREATE OR REPLACE FUNCTION private.auto_assign_primary_caregiver()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid; v_linked uuid; v_primary uuid; v_basis text;
begin
 begin v_actor:=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid;
 exception when others then v_actor:=null; end;
 select p.linked_user_id into v_linked from public.persons p where p.id=new.person_id;

 if v_linked is not null
    and exists(select 1 from public.family_memberships fm
               where fm.family_id=new.family_id and fm.user_id=v_linked and fm.status='active') then
   v_primary:=v_linked; v_basis:='linked_person_self';
 elsif v_actor is not null
    and exists(select 1 from public.family_memberships fm
               where fm.family_id=new.family_id and fm.user_id=v_actor and fm.status='active') then
   v_primary:=v_actor; v_basis:='record_creator';
 else
   v_primary:=null; v_basis:='requires_primary_assignment';
 end if;

 insert into private.medical_primary_responsibilities(
  family_person_id,family_id,primary_user_id,state,authority_basis,assigned_by,assigned_at,created_at,updated_at
 ) values(
  new.id,new.family_id,v_primary,
  case when v_primary is null then 'needs_assignment' else 'active' end,
  v_basis,v_actor,case when v_primary is null then null else now() end,now(),now()
 )
 on conflict(family_person_id) do update
 set family_id=excluded.family_id,
     primary_user_id=coalesce(private.medical_primary_responsibilities.primary_user_id,excluded.primary_user_id),
     state=case when private.medical_primary_responsibilities.state='active' then 'active' else excluded.state end,
     authority_basis=case when private.medical_primary_responsibilities.state='active'
                          then private.medical_primary_responsibilities.authority_basis else excluded.authority_basis end,
     updated_at=now();
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.can_grant_permission(p_family_id uuid, p_family_person_id uuid, p_resource text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_resource text:=case lower(btrim(coalesce(p_resource,'')))
 when 'profile' then 'persons' when 'health' then 'health_data'
 when 'medication' then 'medications' else lower(btrim(coalesce(p_resource,''))) end;
begin
 if p_family_person_id is not null
    and v_resource in ('persons','medications','appointments','health_data','emergency') then
   return private.phms_can_manage_medical_grants((select auth.uid()),p_family_person_id);
 end if;
 if private.is_family_owner(p_family_id)
    or private.user_has_family_role((select auth.uid()),p_family_id,array['admin']) then return true; end if;
 if not private.can_manage_permissions(p_family_id) then return false; end if;
 if p_family_person_id is null then return private.has_family_permission(p_family_id,p_resource,p_action); end if;
 return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.can_grant_role(p_family_id uuid, p_role text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_role='owner' then return false; end if;
  if private.is_family_owner(p_family_id) then
    return p_role in ('admin','caregiver','viewer','patient');
  end if;
  if private.user_has_family_role((select auth.uid()),p_family_id,array['admin']) then
    return p_role in ('caregiver','viewer','patient');
  end if;
  return false;
end
$function$

CREATE OR REPLACE FUNCTION private.can_review_access_request(p_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_family_id uuid;v_person uuid;v_type text;v_route text;
begin
 select family_id,family_person_id,request_type,coalesce(routing_level,'admin')
 into v_family_id,v_person,v_type,v_route from public.permission_requests where id=p_request_id and status='pending';
 if not found or v_user is null then return false;end if;
 if v_person is not null and v_type is distinct from 'role' then return private.phms_can_manage_medical_grants(v_user,v_person); end if;
 if v_route='owner' then return private.is_family_owner(v_family_id);end if;
 return private.is_family_owner(v_family_id) or private.user_has_family_role(v_user,v_family_id,array['admin']);
end; $function$

CREATE OR REPLACE FUNCTION private.enforce_family_person_data_steward()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_fp uuid;
begin
  v_fp:=coalesce(new.family_person_id,old.family_person_id);
  if v_fp is not null and not private.family_person_has_data_steward(v_fp) then
    raise exception 'person_steward_required';
  end if;

  if tg_op='UPDATE'
     and old.family_person_id is distinct from new.family_person_id
     and old.family_person_id is not null
     and not private.family_person_has_data_steward(old.family_person_id) then
    raise exception 'person_steward_required';
  end if;

  return coalesce(new,old);
end
$function$

CREATE OR REPLACE FUNCTION private.ensure_patient_role_for_active_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='active' then
    perform set_config('phms.suppress_access_notifications','on',true);
    insert into public.family_role_assignments(
      family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
    ) values(
      new.family_id,new.user_id,'patient','active',null,coalesce(new.joined_at,now()),now(),now()
    )
    on conflict do nothing;
    perform set_config('phms.suppress_access_notifications','off',true);
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.guard_family_has_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_family_id uuid;
  v_family_exists boolean;
  v_owner_count integer;
begin

  v_family_id := coalesce(new.family_id, old.family_id);

  -- ถ้า Family ถูกลบไปแล้ว ไม่ต้องตรวจ
  select exists (
    select 1
    from public.families f
    where f.id = v_family_id
  )
  into v_family_exists;

  if not v_family_exists then
    return null;
  end if;

  select count(*)
  into v_owner_count
  from public.family_role_assignments fra
  where fra.family_id = v_family_id
    and fra.role = 'owner'
    and fra.status = 'active';

  if v_owner_count < 1 then
    raise exception
      'PHMS_OWNER_REQUIRED: Family must always have at least one active owner';
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_person_linked_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'auth'
AS $function$
begin
  if new.linked_user_id is distinct from old.linked_user_id
     and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'linked_user_id_is_rpc_managed';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.normalize_person_permission_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_caregiver_manage boolean:=false;
  v_pref boolean;
begin
  if coalesce(new.can_create,false)
     or coalesce(new.can_update,false)
     or coalesce(new.can_delete,false) then
    new.can_view:=true;
  end if;

  if coalesce(new.status,'active')='active' then
    select case new.resource
      when 'medications' then ca.can_manage_medications
      when 'appointments' then ca.can_manage_appointments
      when 'health_data' then ca.can_manage_health
      else false
    end
    into v_caregiver_manage
    from public.person_caregiver_assignments ca
    where ca.family_person_id=new.family_person_id
      and ca.caregiver_user_id=new.user_id
      and ca.status='active'
    order by ca.updated_at desc
    limit 1;

    if found then
      new.can_view:=true;
      if coalesce(v_caregiver_manage,false) then
        new.can_create:=true;
        new.can_update:=true;
        new.can_delete:=true;
      end if;
    end if;
  end if;

  if coalesce(new.status,'active')='active'
     and coalesce(new.can_view,false) then
    select p.enabled into v_pref
    from public.person_notification_preferences p
    where p.family_person_id=new.family_person_id
      and p.user_id=new.user_id
      and p.resource=new.resource
    limit 1;
    new.can_receive_notifications:=coalesce(v_pref,true);
  else
    new.can_receive_notifications:=false;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.normalize_phms_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text:=lower(btrim(coalesce(p_value,''))); d int; m int; y int; mon text;
begin
 if s='' then return null; end if;
 s:=replace(replace(replace(s,',',' '),'พ.ศ.',''),'พศ','');
 s:=regexp_replace(s,'\s+',' ','g');
 if s ~ '^\d{4}-\d{1,2}-\d{1,2}$' then
  y:=split_part(s,'-',1)::int; m:=split_part(s,'-',2)::int; d:=split_part(s,'-',3)::int;
 elsif s ~ '^\d{1,2}[/-]\d{1,2}[/-]\d{4}$' then
  d:=split_part(replace(s,'/','-'),'-',1)::int; m:=split_part(replace(s,'/','-'),'-',2)::int; y:=split_part(replace(s,'/','-'),'-',3)::int;
 else
  d:=nullif((regexp_match(s,'^(\d{1,2})\s+'))[1],'')::int;
  y:=nullif((regexp_match(s,'(\d{4})$'))[1],'')::int;
  mon:=replace(btrim(regexp_replace(s,'^\d{1,2}\s+|\s+\d{4}$','','g')),'.','');
  m:=case mon
   when 'มกราคม' then 1 when 'มค' then 1 when 'jan' then 1 when 'january' then 1
   when 'กุมภาพันธ์' then 2 when 'กพ' then 2 when 'feb' then 2 when 'february' then 2
   when 'มีนาคม' then 3 when 'มีค' then 3 when 'mar' then 3 when 'march' then 3
   when 'เมษายน' then 4 when 'เมย' then 4 when 'apr' then 4 when 'april' then 4
   when 'พฤษภาคม' then 5 when 'พค' then 5 when 'may' then 5
   when 'มิถุนายน' then 6 when 'มิย' then 6 when 'jun' then 6 when 'june' then 6
   when 'กรกฎาคม' then 7 when 'กค' then 7 when 'jul' then 7 when 'july' then 7
   when 'สิงหาคม' then 8 when 'สิงหา' then 8 when 'สค' then 8 when 'aug' then 8 when 'august' then 8
   when 'กันยายน' then 9 when 'กันยา' then 9 when 'กย' then 9 when 'sep' then 9 when 'sept' then 9 when 'september' then 9
   when 'ตุลาคม' then 10 when 'ตุลา' then 10 when 'ตค' then 10 when 'oct' then 10 when 'october' then 10
   when 'พฤศจิกายน' then 11 when 'พย' then 11 when 'nov' then 11 when 'november' then 11
   when 'ธันวาคม' then 12 when 'ธันวา' then 12 when 'ธค' then 12 when 'dec' then 12 when 'december' then 12
   else null end;
 end if;
 if y between 2400 and 2700 then y:=y-543; end if;
 if y is null or m is null or d is null then raise exception 'invalid_date_of_birth'; end if;
 return make_date(y,m,d);
exception when datetime_field_overflow or invalid_text_representation then raise exception 'invalid_date_of_birth';
end $function$

CREATE OR REPLACE FUNCTION private.notify_linked_person_record_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_person_id uuid; v_family_id uuid; v_family_person_id uuid; v_recipient uuid; v_actor uuid;
 v_event text:=coalesce(TG_ARGV[0],'person_data_changed'); v_title text:=coalesce(TG_ARGV[1],'ข้อมูลของคุณมีการเปลี่ยนแปลง');
 v_record_id uuid; v_now timestamptz:=now(); v_msg text;
begin
 if TG_TABLE_NAME='persons' then
   v_person_id:=coalesce(NEW.id,OLD.id); v_record_id:=v_person_id;
 elsif TG_TABLE_NAME='appointments' then
   v_person_id:=coalesce(NEW.person_id,OLD.person_id); v_family_id:=coalesce(NEW.family_id,OLD.family_id); v_family_person_id:=coalesce(NEW.family_person_id,OLD.family_person_id); v_record_id:=coalesce(NEW.id,OLD.id);
 elsif TG_TABLE_NAME='health_measurements' then
   v_person_id:=coalesce(NEW.person_id,OLD.person_id); v_record_id:=coalesce(NEW.id,OLD.id);
 elsif TG_TABLE_NAME='person_medications' then
   v_person_id:=coalesce(NEW.person_id,OLD.person_id); v_record_id:=coalesce(NEW.id,OLD.id);
 else return coalesce(NEW,OLD); end if;

 select p.linked_user_id into v_recipient from public.persons p where p.id=v_person_id;
 if v_recipient is null then return coalesce(NEW,OLD); end if;
 begin v_actor:=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid; exception when others then v_actor:=null; end;
 if v_actor is not null and v_actor=v_recipient then return coalesce(NEW,OLD); end if;

 if v_family_person_id is null then
   select fp.id,fp.family_id into v_family_person_id,v_family_id
   from public.family_persons fp where fp.person_id=v_person_id and coalesce(fp.status,'active')='active'
   order by fp.created_at limit 1;
 end if;

 v_msg:=case TG_TABLE_NAME
   when 'persons' then 'รายละเอียดบุคคลของคุณมีการแก้ไข'
   when 'appointments' then 'นัดหมายหรือการตั้งค่าแจ้งเตือนนัดของคุณมีการเปลี่ยนแปลง'
   when 'health_measurements' then 'ข้อมูลสุขภาพของคุณมีการเพิ่มหรือแก้ไข'
   when 'person_medications' then 'ข้อมูลยาของคุณมีการเพิ่มหรือแก้ไข'
   else 'ข้อมูลของคุณมีการเปลี่ยนแปลง' end;

 insert into public.notifications(
  family_id,recipient_user_id,event_type,title,message,related_record_id,channel,priority,status,
  person_id,family_person_id,scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at)
 values(
  v_family_id,v_recipient,v_event,v_title,v_msg,v_record_id,'line','normal','pending',
  v_person_id,v_family_person_id,v_now,v_now,
  jsonb_build_object('table',TG_TABLE_NAME,'operation',TG_OP,'actor_user_id',v_actor),
  'linked-person:'||TG_TABLE_NAME||':'||TG_OP||':'||v_record_id::text||':'||extract(epoch from clock_timestamp())::bigint::text,
  v_now,v_now);
 return coalesce(NEW,OLD);
end $function$

CREATE OR REPLACE FUNCTION private.notify_permission_change_parties()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_family_id uuid;
  v_target_user uuid;
  v_family_person_id uuid;
  v_person_id uuid;
  v_person_owner uuid;
  v_request_actor uuid;
  v_change_author uuid;
  v_resource text;
  v_rec uuid;
  v_target_name text;
  v_actor_name text;
  v_person_name text;
  v_before text;
  v_after text;
  v_role text;
  v_role_active_before boolean;
  v_role_active_after boolean;
  v_change_key text;
  v_change jsonb;
  v_payload jsonb;
  v_merged jsonb;
  v_dedupe text;
begin
  if tg_table_name='person_permissions' then
    v_family_id:=coalesce(new.family_id,old.family_id);
    v_target_user:=coalesce(new.user_id,old.user_id);
    v_family_person_id:=coalesce(new.family_person_id,old.family_person_id);
    v_resource:=coalesce(new.resource,old.resource);
    v_change_author:=coalesce(new.granted_by,old.granted_by);

    select fp.person_id,p.linked_user_id
    into v_person_id,v_person_owner
    from public.family_persons fp
    join public.persons p on p.id=fp.person_id
    where fp.id=v_family_person_id;

    v_before:=case when tg_op='INSERT' then 'ไม่มีสิทธิ์' else
      private.phms_permission_flags_thai(
        old.can_view,old.can_create,old.can_update,old.can_delete,old.can_receive_notifications
      ) end;
    v_after:=case when tg_op='DELETE' then 'ไม่มีสิทธิ์' else
      private.phms_permission_flags_thai(
        new.can_view,new.can_create,new.can_update,new.can_delete,new.can_receive_notifications
      ) end;

    if v_before=v_after then return coalesce(new,old); end if;

  elsif tg_table_name='family_permissions' then
    v_family_id:=coalesce(new.family_id,old.family_id);
    v_target_user:=coalesce(new.user_id,old.user_id);
    v_resource:=coalesce(new.resource,old.resource);
    v_change_author:=coalesce(new.granted_by,old.granted_by);

    v_before:=case when tg_op='INSERT' then 'ไม่มีสิทธิ์' else
      private.phms_permission_flags_thai(
        old.can_view,old.can_create,old.can_update,old.can_delete,old.can_manage_permissions
      ) end;
    v_after:=case when tg_op='DELETE' then 'ไม่มีสิทธิ์' else
      private.phms_permission_flags_thai(
        new.can_view,new.can_create,new.can_update,new.can_delete,new.can_manage_permissions
      ) end;

    if v_before=v_after then return coalesce(new,old); end if;

  elsif tg_table_name='family_role_assignments' then
    v_family_id:=coalesce(new.family_id,old.family_id);
    v_target_user:=coalesce(new.user_id,old.user_id);
    v_resource:='roles';
    v_role:=coalesce(new.role,old.role);
    v_change_author:=coalesce(new.granted_by,old.granted_by);

    if v_role in ('patient','caregiver') then
      return coalesce(new,old);
    end if;
    if v_role='viewer' and v_change_author is null then
      return coalesce(new,old);
    end if;

    v_role_active_before:=case when tg_op='INSERT' then false
      else coalesce(old.status,'active')='active' end;
    v_role_active_after:=case when tg_op='DELETE' then false
      else coalesce(new.status,'active')='active' end;

    if v_role_active_before=v_role_active_after then
      return coalesce(new,old);
    end if;
  else
    return coalesce(new,old);
  end if;

  if coalesce(current_setting('phms.suppress_access_notifications',true),'')='on' then
    return coalesce(new,old);
  end if;

  begin
    v_request_actor:=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid;
  exception when others then
    v_request_actor:=null;
  end;

  -- Manual user edits: affected user + owner of the person's record + Owner/Admin.
  -- System-applied changes: Owner/Admin only, so ordinary members do not get noisy system notices.
  for v_rec in
    select distinct uid
    from (
      select v_target_user uid
      where v_request_actor is not null

      union all

      select v_person_owner
      where v_request_actor is not null
        and v_person_owner is not null

      union all

      select fra.user_id
      from public.family_role_assignments fra
      where fra.family_id=v_family_id
        and fra.status='active'
        and fra.role in ('owner','admin')
    ) x
    where uid is not null
      and (v_request_actor is null or uid<>v_request_actor)
  loop
    v_target_name:=private.family_user_label_for_viewer(
      v_rec,v_family_id,v_target_user
    );

    if v_request_actor is not null then
      v_actor_name:=private.family_user_label_for_viewer(
        v_rec,v_family_id,v_request_actor
      );
    elsif v_change_author is not null then
      v_actor_name:='ระบบ (ตั้งค่าโดย '||
        private.family_user_label_for_viewer(
          v_rec,v_family_id,v_change_author
        )||')';
    else
      v_actor_name:='ระบบ';
    end if;

    if tg_table_name='person_permissions' then
      v_person_name:=private.family_person_label_for_viewer(
        v_rec,v_family_person_id
      );
      v_change_key:='person:'||v_family_person_id::text||':'||v_resource;
      v_change:=jsonb_build_object(
        'kind','person_permission',
        'person_name',v_person_name,
        'resource',v_resource,
        'resource_label',private.phms_resource_thai(v_resource),
        'before',v_before,
        'after',v_after,
        'sort_key',case v_resource
          when 'medications' then '1'
          when 'appointments' then '2'
          when 'health_data' then '3'
          else '9'
        end
      );

    elsif tg_table_name='family_permissions' then
      v_change_key:='family:'||v_resource;
      v_change:=jsonb_build_object(
        'kind','family_permission',
        'resource',v_resource,
        'resource_label',private.phms_resource_thai(v_resource),
        'before',v_before,
        'after',v_after,
        'sort_key',case v_resource
          when 'medications' then '1'
          when 'appointments' then '2'
          when 'health_data' then '3'
          else '9'
        end
      );

    else
      v_change_key:='role:'||v_role;
      v_change:=jsonb_build_object(
        'kind','role',
        'role',v_role,
        'role_label',private.phms_role_thai(v_role),
        'before',case when v_role_active_before then 'มีบทบาท' else 'ไม่มี' end,
        'after',case when v_role_active_after then 'มีบทบาท' else 'ไม่มี' end,
        'sort_key','0'
      );
    end if;

    v_payload:=jsonb_build_object(
      'mode','batched_access_change',
      'actor_kind',case when v_request_actor is null then 'system' else 'user' end,
      'actor_user_id',v_request_actor,
      'configured_by_user_id',case
        when v_request_actor is null then v_change_author
        else null
      end,
      'actor_display',v_actor_name,
      'target_user_id',v_target_user,
      'target_display',v_target_name,
      'transaction_id',txid_current(),
      'changes',jsonb_build_object(v_change_key,v_change)
    );

    v_dedupe:='access-change-batch:'||
      v_family_id::text||':'||
      v_target_user::text||':'||
      v_rec::text||':'||
      txid_current()::text;

    insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,
      channel,priority,status,
      person_id,family_person_id,
      scheduled_for,next_attempt_at,payload,dedupe_key,
      created_at,updated_at
    )
    values(
      v_family_id,v_rec,'access_changed',
      '🔐 สรุปการเปลี่ยนสิทธิ์',
      private.phms_access_change_batch_message(v_payload),
      'line','normal','pending',
      null,null,
      now(),now(),v_payload,v_dedupe,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null
    do update set
      payload=(
        public.notifications.payload || excluded.payload ||
        jsonb_build_object(
          'changes',
          coalesce(public.notifications.payload->'changes','{}'::jsonb) ||
          coalesce(excluded.payload->'changes','{}'::jsonb)
        )
      ),
      title='🔐 สรุปการเปลี่ยนสิทธิ์',
      message=private.phms_access_change_batch_message(
        public.notifications.payload || excluded.payload ||
        jsonb_build_object(
          'changes',
          coalesce(public.notifications.payload->'changes','{}'::jsonb) ||
          coalesce(excluded.payload->'changes','{}'::jsonb)
        )
      ),
      person_id=null,
      family_person_id=null,
      status=case
        when public.notifications.status in ('sent','sending')
          then public.notifications.status
        else 'pending'
      end,
      next_attempt_at=case
        when public.notifications.status in ('sent','sending')
          then public.notifications.next_attempt_at
        else now()
      end,
      updated_at=now();
  end loop;

  return coalesce(new,old);
end
$function$

CREATE OR REPLACE FUNCTION private.person_notification_enabled(p_user_id uuid, p_family_person_id uuid, p_resource text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_resource text:=case lower(btrim(coalesce(p_resource,'')))
  when 'profile' then 'persons' when 'health' then 'health_data'
  when 'medication' then 'medications' else lower(btrim(coalesce(p_resource,''))) end;
 v_pref boolean;
begin
 if p_user_id is null or p_family_person_id is null
    or v_resource not in ('persons','medications','appointments','health_data','emergency') then return false; end if;
 if not private.user_can_access_family_person(p_user_id,p_family_person_id,v_resource,'view') then return false; end if;
 select p.enabled into v_pref from public.person_notification_preferences p
  where p.family_person_id=p_family_person_id and p.user_id=p_user_id and p.resource=v_resource limit 1;
 return coalesce(v_pref,true);
end;
$function$

CREATE OR REPLACE FUNCTION private.phms_apply_appointment_intake_visit_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_catalog'
AS $function$
declare v_d jsonb; v_type text; v_mode text; v_reason text; v_kind text; v_interval integer;
begin
 if new.resource_type<>'appointments' or new.source_type<>'intake_candidate' or new.source_record_id is null then return new; end if;
 select c.normalized_data into v_d from public.data_intake_candidates c
 where c.id=new.source_record_id and c.candidate_type='appointment' and c.person_id=new.person_id;
 if v_d is null then return new; end if;
 v_type:=coalesce(nullif(v_d->>'appointment_type',''),'other');
 v_mode:=case when v_type='walk_in' then 'walk_in' else v_d->>'visit_mode' end;
 if v_mode not in ('walk_in','booked') then v_mode:=null; end if;
 v_reason:=case when v_mode='walk_in' and v_d->>'walk_in_reason' in
 ('queue_full','hospital_advised','no_booking','urgent','other') then v_d->>'walk_in_reason' else null end;
 v_kind:=case when v_type='follow_up' and v_d->>'followup_kind' in
 ('general','chronic_routine','post_treatment','results_review') then v_d->>'followup_kind' else null end;
 if v_type='follow_up' and coalesce(v_d->>'followup_interval_months','') ~ '^[0-9]{1,3}$' then
  v_interval:=(v_d->>'followup_interval_months')::integer;
  if v_interval not between 1 and 120 then v_interval:=null; end if;
 end if;
 if v_mode is null and v_kind is null and v_interval is null and v_reason is null then
  return new;
 end if;
 update public.appointments a set
   appointment_type=case when v_type='walk_in' then 'other' else a.appointment_type end,
   visit_mode=coalesce(v_mode,a.visit_mode),
   walk_in_reason=v_reason,
   walk_in_note=case when v_mode='walk_in' then nullif(btrim(v_d->>'walk_in_note'),'') else null end,
   followup_kind=v_kind,
   followup_interval_months=v_interval
 where a.id=new.record_id and a.person_id=new.person_id and a.deleted_at is null
   and (
    a.visit_mode is distinct from coalesce(v_mode,a.visit_mode)
    or a.walk_in_reason is distinct from v_reason
    or a.followup_kind is distinct from v_kind
    or a.followup_interval_months is distinct from v_interval
   );
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.phms_appointment_master_guard_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_hospital text;
  v_org uuid;
  v_unit uuid;
  v_department text;
  v_unit_name text;
  v_unit_code text;
  v_norm text;
begin
  if new.contact_email is not null then
    new.contact_email:=nullif(lower(btrim(new.contact_email)),'');
    if new.contact_email in ('-','—','n/a','na','ไม่มี') then
      new.contact_email:=null;
    elsif new.contact_email is not null
      and new.contact_email !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}$' then
      raise exception 'invalid_contact_email';
    end if;
  end if;

  v_hospital:=nullif(btrim(coalesce(new.hospital_name,'')),'');
  if v_hospital is not null then
    v_org:=coalesce(new.organization_id,private.phms_canonical_hospital_org_id(v_hospital));

    if v_org is null then
      v_norm:=private.phms_normalize_directory_alias(v_hospital);
      select a.organization_id into v_org
      from private.healthcare_directory_aliases a
      where a.entity_type='organization'
        and a.is_active
        and a.normalized_alias=v_norm
      order by case a.confidence when 'high' then 0 when 'medium' then 1 else 2 end,a.updated_at desc
      limit 1;
    end if;

    if v_org is null then
      select o.id into v_org
      from public.healthcare_organizations o
      where o.deleted_at is null
        and private.phms_normalize_directory_alias(
          concat_ws(' ',o.name,o.branch_name,o.external_code)
        )=private.phms_normalize_directory_alias(v_hospital)
      order by o.updated_at desc
      limit 1;
    end if;

    if v_org is null then
      begin
        insert into public.healthcare_organizations(
          organization_type,name,source,is_verified,verified_at,verified_by
        ) values(
          'hospital',private.phms_canonical_hospital_display(v_hospital),
          'confirmed_appointment_seed',true,now(),new.created_by
        )
        returning id into v_org;
      exception when unique_violation then
        select o.id into v_org
        from public.healthcare_organizations o
        where o.deleted_at is null
          and lower(o.name)=lower(private.phms_canonical_hospital_display(v_hospital))
        order by o.updated_at desc
        limit 1;
      end;
    end if;

    new.organization_id:=v_org;

    insert into private.healthcare_directory_aliases(
      entity_type,organization_id,alias,normalized_alias,source,confidence
    )
    values(
      'organization',v_org,v_hospital,
      private.phms_normalize_directory_alias(v_hospital),
      'confirmed_appointment_seed','high'
    )
    on conflict (entity_type,organization_id,normalized_alias)
    do update set alias=excluded.alias,source=excluded.source,confidence='high',is_active=true,updated_at=now();
  end if;

  v_department:=private.phms_normalize_appointment_department(new.department);
  if new.organization_id is not null and v_department is not null then
    new.department:=v_department;
    v_unit:=coalesce(private.phms_match_service_unit(new.organization_id,v_department),new.service_unit_id);

    if v_unit is null then
      v_unit_name:=btrim(regexp_replace(v_department,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i'));
      v_unit_code:=nullif(btrim(substring(v_department from '[(]([^)]*)[)][[:space:]]*$')),'');

      begin
        insert into public.healthcare_service_units(
          organization_id,unit_type,name,code,source,is_verified,verified_at,verified_by
        ) values(
          new.organization_id,'department',v_unit_name,v_unit_code,
          'confirmed_appointment_seed',true,now(),new.created_by
        )
        returning id into v_unit;
      exception when unique_violation then
        select u.id into v_unit
        from public.healthcare_service_units u
        where u.organization_id=new.organization_id
          and u.deleted_at is null
          and lower(u.name)=lower(v_unit_name)
        order by u.updated_at desc
        limit 1;
      end;

      insert into private.healthcare_directory_aliases(
        entity_type,organization_id,service_unit_id,alias,normalized_alias,source,confidence
      )
      select 'service_unit',new.organization_id,v_unit,x.alias,
             private.phms_normalize_directory_alias(x.alias),
             'confirmed_appointment_seed','high'
      from (values(v_unit_name),(v_unit_code),(v_department)) x(alias)
      where nullif(btrim(coalesce(x.alias,'')),'') is not null
      on conflict (entity_type,organization_id,normalized_alias)
      do update set service_unit_id=excluded.service_unit_id,alias=excluded.alias,
                    source=excluded.source,confidence='high',is_active=true,updated_at=now();
    end if;

    new.service_unit_id:=v_unit;

    update public.healthcare_service_units u
    set location_detail=case
          when nullif(btrim(coalesce(u.location_detail,'')),'') is null
          then nullif(btrim(coalesce(new.location_detail,'')),'')
          else u.location_detail end,
        phone=case
          when nullif(btrim(coalesce(u.phone,'')),'') is null
           and nullif(btrim(coalesce(new.contact_phone,'')),'') is not null
           and new.contact_phone ~ '[0-9]'
          then btrim(new.contact_phone)
          else u.phone end,
        email=case
          when nullif(btrim(coalesce(u.email,'')),'') is null
           and nullif(btrim(coalesce(new.contact_email,'')),'') is not null
          then lower(btrim(new.contact_email))
          else u.email end,
        source=case when u.source='appointment_history_seed' then 'confirmed_appointment_seed' else u.source end,
        is_verified=true,
        verified_at=coalesce(u.verified_at,now()),
        verified_by=coalesce(u.verified_by,new.created_by),
        updated_at=now()
    where u.id=v_unit;
  elsif new.organization_id is null then
    new.service_unit_id:=null;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_assert_destructive_changes_allowed(p_operation text DEFAULT 'destructive_change'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_env public.phms_runtime_environment%rowtype;
begin
  select * into v_env
  from public.phms_runtime_environment
  where singleton = true;

  if not found then
    raise exception 'phms_environment_not_configured';
  end if;

  if coalesce(v_env.allow_destructive_changes,false) is not true then
    raise exception 'destructive_change_blocked_in_%: %', v_env.environment, coalesce(p_operation,'destructive_change');
  end if;
end;
$function$

