CREATE OR REPLACE FUNCTION private.phms_can_access_person_impl(p_person_id uuid, p_resource text DEFAULT 'health_data'::text, p_action text DEFAULT 'view'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_resource text:=case lower(btrim(coalesce(p_resource,'')))
    when 'health' then 'health_data'
    when 'documents' then 'documents'
    when 'document' then 'documents'
    when 'medication' then 'medications'
    else lower(btrim(coalesce(p_resource,'')))
  end;
  v_action text:=lower(btrim(coalesce(p_action,'view')));
begin
  if v_uid is null or p_person_id is null then return false; end if;
