$function$

CREATE OR REPLACE FUNCTION private.phms_canonical_hospital_code(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v text:=nullif(btrim(coalesce(p_value,'')),'');
  n text;
begin
  if v is null then return null; end if;
  n:=lower(regexp_replace(v,'[^0-9a-zก-๙]+','','g'));
  if n='chg9' or n like '%จุฬารัตน์9%' then return 'CHG-9'; end if;
  if n='chg3' or n like '%จุฬารัตน์3%' then return 'CHG-3'; end if;
  if n='rama' or n like '%รามาธิบดี%' then return 'RAMA'; end if;
  if n='kmch' or n like '%พระจอมเกล้าเจ้าคุณทหาร%' then return 'KMCH'; end if;
  if n='lkb' or n like '%นคราภิบาล%'
    or n in ('ลาดกระบัง','รพลาดกระบัง','โรงพยาบาลลาดกระบัง') then return 'LKB'; end if;
  return null;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_clean_appointment_preparation_text(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_expanded text;
  v_line text;
  v_check text;
  v_out text[] := array[]::text[];
begin
  if nullif(btrim(coalesce(p_text,'')),'') is null then
    return null;
  end if;

  v_expanded := replace(replace(p_text,chr(1),''),chr(2),'');

  -- Split inline numbered items with or without a space after the marker.
  -- "8.00" is not split because the character after "." is a digit.
  v_expanded := regexp_replace(
    v_expanded,
    '([[:space:]])([0-9]{1,2}[.)])([^0-9[:space:]])',
    ('\1' || chr(10) || '\2 ' || '\3'),
    'g'
  );
  v_expanded := regexp_replace(
    v_expanded,
    '([[:space:]])([0-9]{1,2}[.)][[:space:]]+)',
    ('\1' || chr(10) || '\2'),
    'g'
  );

  foreach v_line in array regexp_split_to_array(v_expanded,E'\n+')
  loop
    v_line := btrim(v_line);
    if v_line='' then continue; end if;

    v_check := regexp_replace(
      v_line,
      '^([0-9]{1,2}[.)]|[-•☐☑✅⬜])[[:space:]]*',
      '',
      'i'
    );

    if v_check ~* '^(ติดต่อ|เบอร์ติดต่อ|โทรศัพท์|อีเมล|email|แพทย์|หมอ|ชื่อแพทย์|สถานพยาบาล|โรงพยาบาล|รพ|HN|เลข[[:space:]]*HN|เลขผู้ป่วย|แผนก|คลินิก|แผนก/คลินิก|จุดนัด|สถานที่|อาคาร/ชั้น|จุด/อาคาร/ชั้น|สิทธิรักษา|สิทธิ|สิทธิการรักษา|หมายเหตุ|ประเภทนัด|ชนิดนัด|สถานะนัด|บันทึกเป็น)[[:space:]]*[:：=]'
    then
      continue;
    end if;

    v_out := array_append(v_out,v_line);
  end loop;

  if cardinality(v_out)=0 then return null; end if;
  return array_to_string(v_out,E'\n');
end
$function$

CREATE OR REPLACE FUNCTION private.phms_commit_appointment_candidate(p_candidate_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_result jsonb;
  v_c public.data_intake_candidates%rowtype;
  v_d jsonb;
  v_id uuid;
  v_interval integer;
  v_preventive_interval integer;
  v_visit_time_known boolean;
  v_plan jsonb;
begin
  v_result:=private.phms_commit_appointment_candidate_base_20261010(
    p_candidate_id,p_actor_user_id
  );

  v_id:=private.phms_try_uuid(v_result->>'appointment_id');
  if v_id is null then
    return v_result;
  end if;

  select * into v_c
  from public.data_intake_candidates
  where id=p_candidate_id;

  if not found then
    return v_result;
  end if;

  v_d:=coalesce(v_c.normalized_data,'{}'::jsonb);

  if coalesce(v_d->>'followup_interval_months','') ~ '^[0-9]+$' then
    v_interval:=greatest(1,least((v_d->>'followup_interval_months')::int,120));
  else
    v_interval:=null;
  end if;

  if coalesce(v_d->>'preventive_interval_months','') ~ '^[0-9]+$' then
    v_preventive_interval:=greatest(1,least((v_d->>'preventive_interval_months')::int,120));
  else
    v_preventive_interval:=null;
  end if;

  if lower(coalesce(v_d->>'visit_time_known','')) in ('true','false') then
    v_visit_time_known:=(v_d->>'visit_time_known')::boolean;
  else
    v_visit_time_known:=true;
  end if;

  update public.appointments
  set visit_mode=case
        when nullif(btrim(v_d->>'visit_mode'),'') in ('booked','walk_in','unspecified')
          then nullif(btrim(v_d->>'visit_mode'),'')
        else visit_mode
      end,
      walk_in_reason=case
        when nullif(btrim(v_d->>'walk_in_reason'),'') in ('queue_full','hospital_advised','no_booking','urgent','other')
          then nullif(btrim(v_d->>'walk_in_reason'),'')
        else null
      end,
      walk_in_note=nullif(btrim(v_d->>'walk_in_note'),''),
      followup_kind=case
        when nullif(btrim(v_d->>'followup_kind'),'') in ('general','chronic_routine','post_treatment','results_review')
          then nullif(btrim(v_d->>'followup_kind'),'')
        else null
      end,
      followup_interval_months=case
        when appointment_type='follow_up' then v_interval
        else null
      end,
      preventive_interval_months=case
        when appointment_type in ('checkup','vaccination') then v_preventive_interval
        else null
      end,
      planned_visit_date=case
        when coalesce(v_d->>'planned_visit_date','') ~ '^\d{4}-\d{2}-\d{2}$'
          then (v_d->>'planned_visit_date')::date
        else planned_visit_date
      end,
      visit_time_known=v_visit_time_known,
      early_visit_of_appointment_id=private.phms_try_uuid(v_d->>'early_visit_of_appointment_id'),
      walk_in_doctor_status=case
        when nullif(btrim(v_d->>'walk_in_doctor_status'),'') in ('pending','same_confirmed','on_duty_unknown','different_unknown','other_confirmed')
          then nullif(btrim(v_d->>'walk_in_doctor_status'),'')
        else null
      end,
      updated_at=now()
  where id=v_id;

  v_plan:=private.phms_sync_recurring_care_plan_from_appointment(v_id,p_actor_user_id);

  return v_result || jsonb_build_object(
    'recurring_care_plan',v_plan
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_commit_appointment_candidate_base_20261010(p_candidate_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_c public.data_intake_candidates%rowtype;
  v_ds public.data_intake_sessions%rowtype;
  v_s public.data_intake_sources%rowtype;
  v_d jsonb;
  v_existing uuid;
  v_id uuid;
  v_at timestamptz;
  v_title text;
  v_status text;
  v_arrival int:=0;
  v_hn text;
  v_vn text;
begin
  select * into v_c
  from public.data_intake_candidates
  where id=p_candidate_id
  for update;

  if not found then raise exception 'candidate_not_found'; end if;
  if v_c.candidate_type<>'appointment' then raise exception 'candidate_type_not_appointment'; end if;
  if v_c.review_status not in ('accepted','committed') then raise exception 'candidate_not_accepted'; end if;
  if v_c.person_id is null then raise exception 'person_required'; end if;

  v_existing:=private.phms_existing_candidate_record(v_c.id,'appointments');
  if v_existing is not null then
    return jsonb_build_object(
      'ok',true,'idempotent_replay',true,
      'resource_type','appointment',
      'appointment_id',v_existing
    );
  end if;

  select * into v_ds
  from public.data_intake_sessions
  where id=v_c.session_id;
  if not found then raise exception 'session_not_found'; end if;

  if v_ds.person_id is distinct from v_c.person_id then
    raise exception 'person_mismatch_candidate_session';
  end if;

  if v_c.source_id is not null then
    select * into v_s
    from public.data_intake_sources
    where id=v_c.source_id;
  end if;

  v_d:=coalesce(v_c.normalized_data,'{}'::jsonb);
  v_at:=private.phms_try_timestamptz(v_d->>'appointment_at');
  if v_at is null then raise exception 'appointment_at_required'; end if;

  v_title:=nullif(btrim(coalesce(
    v_d->>'title',
    v_d->>'appointment_type',
    v_d->>'department',
    v_d->>'hospital_name',
    'นัดหมาย'
  )),'');
  if v_title is null then v_title:='นัดหมาย'; end if;

  v_status:=lower(coalesce(nullif(btrim(v_d->>'status'),''),'scheduled'));
  if v_status not in ('scheduled','confirmed','completed','no_show','cancelled') then
    v_status:='scheduled';
  end if;

  if coalesce(v_d->>'arrival_lead_minutes','') ~ '^[0-9]+$' then
    v_arrival:=greatest(0,least((v_d->>'arrival_lead_minutes')::int,720));
  end if;

  v_hn:=nullif(btrim(v_d->>'hospital_hn'),'');
  v_vn:=nullif(btrim(v_d->>'hospital_vn'),'');


  if nullif(v_d->>'investigation_of_appointment_id','') is not null
     or nullif(v_d->>'referral_from_appointment_id','') is not null
     or nullif(v_d->>'followup_of_appointment_id','') is not null
  then
    if exists(
      select 1 from (
        values (
          private.phms_try_uuid(v_d->>'investigation_of_appointment_id')),
          (private.phms_try_uuid(v_d->>'referral_from_appointment_id')),
          (private.phms_try_uuid(v_d->>'followup_of_appointment_id'))
      ) as refs(id)
      left join public.appointments old on old.id=refs.id and old.deleted_at is null
      where refs.id is not null and (
        old.id is null or old.person_id is distinct from v_c.person_id
        or (old.appointment_at is not null and old.appointment_at>=v_at)
      )
    ) then
      raise exception 'appointment_reference_invalid_or_wrong_person';
    end if;
  end if;

  insert into public.appointments(
    family_id,family_person_id,person_id,
    title,hospital_name,department,doctor_name,appointment_at,note,status,
    organization_id,service_unit_id,clinician_id,encounter_id,
    appointment_type,external_reference,source_document_id,created_by,
    location_detail,contact_phone,contact_email,coverage_type,preparation_notes,
    hospital_hn,hospital_vn,arrival_lead_minutes,care_topic,
    followup_of_appointment_id,rescheduled_from_appointment_id,
    referral_from_appointment_id,referral_source_kind,investigation_of_appointment_id,reference_note,
    completed_at,no_show_at,cancelled_at
  )
  values(
    v_ds.family_id,
    v_ds.family_person_id,
    v_c.person_id,
    v_title,
    nullif(btrim(v_d->>'hospital_name'),''),
    nullif(btrim(v_d->>'department'),''),
    nullif(btrim(v_d->>'doctor_name'),''),
    v_at,
    nullif(btrim(coalesce(v_d->>'note',v_d->>'notes')),''),
    v_status,
    private.phms_try_uuid(v_d->>'organization_id'),
    private.phms_try_uuid(v_d->>'service_unit_id'),
    private.phms_try_uuid(v_d->>'clinician_id'),
    private.phms_try_uuid(v_d->>'encounter_id'),
    nullif(btrim(v_d->>'appointment_type'),''),
    nullif(btrim(v_d->>'external_reference'),''),
    v_s.source_document_id,
    p_actor_user_id,
    nullif(btrim(v_d->>'location_detail'),''),
    nullif(btrim(v_d->>'contact_phone'),''),
    nullif(btrim(v_d->>'contact_email'),''),
    nullif(btrim(v_d->>'coverage_type'),''),
    nullif(btrim(v_d->>'preparation_notes'),''),
    v_hn,
    v_vn,
    v_arrival,
    nullif(btrim(v_d->>'care_topic'),''),
    private.phms_try_uuid(v_d->>'followup_of_appointment_id'),
    private.phms_try_uuid(v_d->>'rescheduled_from_appointment_id'),
    private.phms_try_uuid(v_d->>'referral_from_appointment_id'),
    nullif(btrim(v_d->>'referral_source_kind'),''),
    private.phms_try_uuid(v_d->>'investigation_of_appointment_id'),
    nullif(btrim(v_d->>'reference_note'),''),
    case when v_status='completed' then v_at else null end,
    case when v_status='no_show' then v_at else null end,
    case when v_status='cancelled' then v_at else null end
  )
  returning id into v_id;

  if v_hn is not null then
    perform private.phms_sync_person_hospital_hn(
      v_c.person_id,
      private.phms_try_uuid(v_d->>'organization_id'),
      nullif(btrim(v_d->>'hospital_name'),''),
      v_hn,
      p_actor_user_id
    );
  end if;

  if v_vn is not null then
    perform private.phms_sync_person_hospital_vn(
      v_c.person_id,
      private.phms_try_uuid(v_d->>'organization_id'),
      nullif(btrim(v_d->>'hospital_name'),''),
      v_vn,
      p_actor_user_id
    );
  end if;

  perform private.phms_write_intake_provenance(
    v_c.id,'appointments',v_id,p_actor_user_id
  );

  perform private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,'idempotent_replay',false,
    'resource_type','appointment',
    'appointment_id',v_id,
    'status',v_status,
    'historical_record',v_status in ('completed','no_show','cancelled')
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_commit_confirmed_document_core(p_line_user_id text, p_source_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_ds public.data_intake_sessions%rowtype;
  v_c public.data_intake_candidates%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_code text:=lower(btrim(coalesce(p_source_code,'')));
  v_count integer;
  v_existing uuid;
  v_doc_id uuid;
  v_title text;
begin
  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources
  where submitted_by=v_line.user_id
    and lower(id::text) like v_code||'%'
  limit 1;

  select * into v_ds
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;

  if v_ds.status not in ('confirmed','committed') then
    raise exception 'confirmed_intake_required';
  end if;

  select * into v_c
  from public.data_intake_candidates
  where source_id=v_source.id
    and candidate_type='medical_document'
    and review_status in ('accepted','committed')
  order by ordinal
  limit 1;

  if not found then raise exception 'medical_document_candidate_required'; end if;
  if jsonb_array_length(coalesce(v_c.conflict_data->'blocking_conflicts','[]'::jsonb))>0 then
    raise exception 'candidate_conflict_blocked';
  end if;

  v_existing:=private.phms_existing_candidate_record(v_c.id,'medical_documents');
  if v_existing is not null then
    return jsonb_build_object(
      'ok',true,'idempotent_replay',true,
      'document_id',v_existing,'source_id',v_source.id
    );
  end if;

  if v_source.storage_asset_id is null then raise exception 'storage_asset_required'; end if;
  select * into v_asset from public.phms_storage_assets where id=v_source.storage_asset_id;
  if not found then raise exception 'storage_asset_not_found'; end if;
  if v_asset.person_id is not null and v_asset.person_id<>v_ds.person_id then
    raise exception 'person_mismatch_storage_asset';
  end if;

  v_title:=nullif(btrim(coalesce(
    v_c.normalized_data->>'title',
    v_asset.original_filename,
    v_source.document_type
  )),'');
  if v_title is null then v_title:='เอกสารสุขภาพ'; end if;

  insert into public.medical_documents(
    person_id,encounter_id,organization_id,document_type,document_date,title,
    storage_bucket,storage_path,source_channel,original_filename,mime_type,
    checksum_sha256,extraction_status,uploaded_by,metadata,storage_asset_id
  )
  values(
    v_ds.person_id,
    private.phms_try_uuid(v_c.normalized_data->>'encounter_id'),
    private.phms_try_uuid(v_c.normalized_data->>'organization_id'),
    coalesce(nullif(btrim(v_source.document_type),''),'medical_document'),
    private.phms_try_date(v_c.normalized_data->>'document_date'),
    v_title,
    v_asset.bucket_id,v_asset.object_name,'line',
    v_asset.original_filename,v_asset.mime_type,v_asset.checksum_sha256,
    coalesce(nullif(v_source.source_metadata->>'extraction_status',''),'completed'),
    v_line.user_id,
    jsonb_build_object(
      'intake_session_id',v_ds.id,
      'intake_source_id',v_source.id,
      'intake_candidate_id',v_c.id,
      'canonical_commit',true
    ),
    v_asset.id
  )
  returning id into v_doc_id;

  perform private.phms_write_intake_provenance(
    v_c.id,'medical_documents',v_doc_id,v_line.user_id
  );

  update public.data_intake_candidates
  set review_status='committed',
      reconciliation_data=coalesce(reconciliation_data,'{}'::jsonb)
        || jsonb_build_object(
          'canonical_commit',true,
          'canonical_resource','medical_documents',
          'canonical_record_id',v_doc_id,
          'committed_at',now()
        ),
      updated_at=now()
  where id=v_c.id;

  if not exists(
    select 1 from public.data_intake_candidates c
    where c.session_id=v_ds.id
      and c.review_status not in ('rejected','committed')
  ) then
    update public.data_intake_sessions
    set status='committed',updated_at=now()
    where id=v_ds.id;
  end if;

  update public.data_intake_sources
  set source_document_id=v_doc_id,
      source_metadata=coalesce(source_metadata,'{}'::jsonb)
        || jsonb_build_object(
          'canonical_commit',true,
          'canonical_document_id',v_doc_id,
          'committed_at',now()
        )
  where id=v_source.id;

  update public.phms_storage_assets
  set metadata=coalesce(metadata,'{}'::jsonb)
      || jsonb_build_object(
        'retain_for_provenance',true,
        'canonical_document_id',v_doc_id
      ),
      updated_at=now()
  where id=v_asset.id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  )
  values(
    v_ds.family_id,v_line.user_id,v_ds.family_person_id,
    'crud_create','document',v_doc_id,
    jsonb_build_object('source_id',v_source.id,'storage_asset_id',v_asset.id),
    'Document created from confirmed intake'
  );

  return jsonb_build_object(
    'ok',true,'idempotent_replay',false,
    'document_id',v_doc_id,'source_id',v_source.id,
    'canonical_commit',true
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_commit_health_measurement_candidate(p_candidate_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_c public.data_intake_candidates%rowtype;
  v_d jsonb;
  v_existing uuid;
  v_id uuid;
  v_type text;
  v_at timestamptz;
  v_value_numeric numeric;
  v_value_text text;
  v_systolic numeric;
  v_diastolic numeric;
begin
  select * into v_c
  from public.data_intake_candidates
  where id=p_candidate_id
  for update;

  if not found then raise exception 'candidate_not_found'; end if;
  if v_c.candidate_type not in ('health_measurement','measurement') then
    raise exception 'candidate_type_not_health_measurement';
  end if;
  if v_c.review_status not in ('accepted','committed') then raise exception 'candidate_not_accepted'; end if;
  if v_c.person_id is null then raise exception 'person_required'; end if;

  v_existing:=private.phms_existing_candidate_record(v_c.id,'health_measurements');
  if v_existing is not null then
    return jsonb_build_object(
      'ok',true,'idempotent_replay',true,
      'resource_type','health_measurement',
      'health_measurement_id',v_existing
    );
  end if;

  v_d:=coalesce(v_c.normalized_data,'{}'::jsonb);

  v_type:=nullif(private.phms_normalize_dedupe_text(
    coalesce(v_d->>'measurement_type',v_d->>'type')
  ),'');
  if v_type is null then raise exception 'measurement_type_required'; end if;

  v_at:=private.phms_try_timestamptz(
    coalesce(v_d->>'measured_at',v_d->>'measurement_at')
  );
  if v_at is null then raise exception 'measured_at_required'; end if;

  v_value_numeric:=private.phms_try_numeric(v_d->>'value_numeric');
  v_value_text:=nullif(btrim(v_d->>'value_text'),'');
  v_systolic:=private.phms_try_numeric(v_d->>'systolic');
  v_diastolic:=private.phms_try_numeric(v_d->>'diastolic');

  if v_value_numeric is null
     and v_value_text is null
     and v_systolic is null
     and v_diastolic is null then
    raise exception 'measurement_value_required';
  end if;

  if (v_systolic is null) <> (v_diastolic is null) then
    raise exception 'blood_pressure_requires_systolic_and_diastolic';
  end if;

  insert into public.health_measurements(
    person_id,measurement_type,measured_at,
    value_numeric,value_text,unit,systolic,diastolic,
    context,notes,source_type,created_by
  )
  values(
    v_c.person_id,
    v_type,
    v_at,
    v_value_numeric,
    v_value_text,
    nullif(btrim(v_d->>'unit'),''),
    v_systolic,
    v_diastolic,
    nullif(btrim(v_d->>'context'),''),
    nullif(btrim(coalesce(v_d->>'notes',v_d->>'note')),''),
    'intake',
    p_actor_user_id
  )
  returning id into v_id;

  perform private.phms_write_intake_provenance(
    v_c.id,'health_measurements',v_id,p_actor_user_id
  );

  return jsonb_build_object(
    'ok',true,'idempotent_replay',false,
    'resource_type','health_measurement',
    'health_measurement_id',v_id
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_commit_medication_candidate(p_candidate_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_c public.data_intake_candidates%rowtype;
  v_d jsonb;
  v_existing uuid;
  v_medication_id uuid;
  v_person_medication_id uuid;
  v_regimen_id uuid;
  v_generic text;
  v_brand text;
  v_key text;
  v_status text;
  v_strength numeric;
  v_start date;
  v_end date;
  v_has_regimen boolean;
  v_effective_from timestamptz;
  v_effective_to timestamptz;
begin
  select * into v_c
  from public.data_intake_candidates
  where id=p_candidate_id
  for update;

  if not found then raise exception 'candidate_not_found'; end if;
  if v_c.candidate_type<>'medication' then raise exception 'candidate_type_not_medication'; end if;
  if v_c.review_status not in ('accepted','committed') then raise exception 'candidate_not_accepted'; end if;
  if v_c.person_id is null then raise exception 'person_required'; end if;

  v_existing := private.phms_existing_candidate_record(v_c.id,'person_medications');
  if v_existing is not null then
    select rp.record_id into v_regimen_id
    from public.record_provenance rp
    where rp.source_type='intake_candidate'
      and rp.source_record_id=v_c.id
      and rp.resource_type='medication_regimens'
    limit 1;

    select rp.record_id into v_medication_id
    from public.record_provenance rp
    where rp.source_type='intake_candidate'
      and rp.source_record_id=v_c.id
      and rp.resource_type='medication_master'
    limit 1;

    return jsonb_strip_nulls(jsonb_build_object(
      'ok',true,'idempotent_replay',true,
      'resource_type','medication',
      'medication_master_id',v_medication_id,
      'person_medication_id',v_existing,
      'medication_regimen_id',v_regimen_id
    ));
  end if;

  v_d := coalesce(v_c.normalized_data,'{}'::jsonb);
  v_medication_id := private.phms_try_uuid(v_d->>'medication_id');

  if v_medication_id is not null then
    if not exists(
      select 1 from public.medication_master
      where id=v_medication_id and deleted_at is null
    ) then
      raise exception 'medication_id_not_found';
    end if;
  else
    v_generic := nullif(btrim(coalesce(
      v_d->>'generic_name',
      v_d->>'medication_name',
      v_d->>'name',
      v_d->>'brand_name'
    )),'');
    v_brand := nullif(btrim(v_d->>'brand_name'),'');
    v_strength := private.phms_try_numeric(v_d->>'strength_value');

    if v_generic is null then
      raise exception 'medication_name_required';
    end if;

    v_key := nullif(private.phms_normalize_dedupe_text(v_d->>'normalized_key'),'');
    if v_key is null then
      v_key := private.phms_normalize_dedupe_text(
        concat_ws('|',
          v_generic,
          coalesce(v_brand,''),
          coalesce(v_d->>'strength_value',''),
          coalesce(v_d->>'strength_unit',''),
          coalesce(v_d->>'dosage_form','')
        )
      );
    end if;

    select mm.id into v_medication_id
    from public.medication_master mm
    where mm.normalized_key=v_key
      and mm.deleted_at is null
    limit 1;

    if v_medication_id is null then
      insert into public.medication_master(
        generic_name,brand_name,strength_value,strength_unit,
        concentration_text,dosage_form,default_route,standard_unit,
        active_ingredient_text,normalized_key,status
      )
      values(
        v_generic,
        v_brand,
        v_strength,
        nullif(btrim(v_d->>'strength_unit'),''),
        nullif(btrim(v_d->>'concentration_text'),''),
        nullif(btrim(v_d->>'dosage_form'),''),
        nullif(btrim(coalesce(v_d->>'default_route',v_d->>'route')),''),
        nullif(btrim(v_d->>'standard_unit'),''),
        nullif(btrim(v_d->>'active_ingredient_text'),''),
        v_key,
        'active'
      )
      on conflict do nothing
      returning id into v_medication_id;

      if v_medication_id is null then
        select mm.id into v_medication_id
        from public.medication_master mm
        where mm.normalized_key=v_key
          and mm.deleted_at is null
        limit 1;
      end if;
    end if;
  end if;

  if v_medication_id is null then raise exception 'medication_master_resolution_failed'; end if;

  v_status := lower(coalesce(nullif(btrim(v_d->>'status'),''),'regular'));
  if v_status not in ('regular','prn','paused','discontinued','completed') then
    v_status := 'regular';
  end if;

  v_start := private.phms_try_date(v_d->>'start_date');
  v_end := private.phms_try_date(v_d->>'end_date');

  insert into public.person_medications(
    person_id,medication_id,indication,related_condition_id,status,
    prescriber_id,organization_id,service_unit_id,
    start_date,end_date,notes,created_by
  )
  values(
    v_c.person_id,
    v_medication_id,
    nullif(btrim(v_d->>'indication'),''),
    private.phms_try_uuid(v_d->>'related_condition_id'),
    v_status,
    private.phms_try_uuid(v_d->>'prescriber_id'),
    private.phms_try_uuid(v_d->>'organization_id'),
    private.phms_try_uuid(v_d->>'service_unit_id'),
    v_start,
    v_end,
    nullif(btrim(coalesce(v_d->>'notes',v_d->>'note')),''),
    p_actor_user_id
  )
  returning id into v_person_medication_id;

  perform private.phms_write_intake_provenance(
    v_c.id,'medication_master',v_medication_id,p_actor_user_id
  );
  perform private.phms_write_intake_provenance(
    v_c.id,'person_medications',v_person_medication_id,p_actor_user_id
  );

  v_has_regimen :=
    nullif(btrim(v_d->>'dose_value'),'') is not null
    or nullif(btrim(v_d->>'dose_unit'),'') is not null
    or nullif(btrim(v_d->>'dose_text'),'') is not null
    or nullif(btrim(v_d->>'frequency_type'),'') is not null
    or nullif(btrim(v_d->>'frequency_value'),'') is not null
    or nullif(btrim(v_d->>'frequency_unit'),'') is not null
    or nullif(btrim(v_d->>'route'),'') is not null
    or nullif(btrim(v_d->>'meal_relation'),'') is not null
    or nullif(btrim(v_d->>'instructions'),'') is not null
    or jsonb_typeof(v_d->'time_of_day')='array'
    or jsonb_typeof(v_d->'exact_times')='array';

  if v_has_regimen then
    v_effective_from := coalesce(
      private.phms_try_timestamptz(v_d->>'effective_from'),
      case when v_start is not null then v_start::timestamptz else now() end
    );
    v_effective_to := private.phms_try_timestamptz(v_d->>'effective_to');

    insert into public.medication_regimens(
      person_medication_id,
      dose_value,dose_unit,dose_text,
      frequency_type,frequency_value,frequency_unit,
      route,administration_site,meal_relation,
      time_of_day,exact_times,
      max_daily_dose,max_daily_dose_unit,
      instructions,effective_from,effective_to,is_current,created_by
    )
    values(
      v_person_medication_id,
      private.phms_try_numeric(v_d->>'dose_value'),
      nullif(btrim(v_d->>'dose_unit'),''),
      nullif(btrim(v_d->>'dose_text'),''),
      nullif(btrim(v_d->>'frequency_type'),''),
      private.phms_try_numeric(v_d->>'frequency_value'),
      nullif(btrim(v_d->>'frequency_unit'),''),
      nullif(btrim(v_d->>'route'),''),
      nullif(btrim(v_d->>'administration_site'),''),
      nullif(btrim(v_d->>'meal_relation'),''),
      private.phms_jsonb_text_array(v_d->'time_of_day'),
      private.phms_jsonb_time_array(v_d->'exact_times'),
      private.phms_try_numeric(v_d->>'max_daily_dose'),
      nullif(btrim(v_d->>'max_daily_dose_unit'),''),
      nullif(btrim(v_d->>'instructions'),''),
      v_effective_from,
      v_effective_to,
      v_effective_to is null or v_effective_to>now(),
      p_actor_user_id
    )
    returning id into v_regimen_id;

    perform private.phms_write_intake_provenance(
      v_c.id,'medication_regimens',v_regimen_id,p_actor_user_id
    );
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'ok',true,'idempotent_replay',false,
    'resource_type','medication',
    'medication_master_id',v_medication_id,
    'person_medication_id',v_person_medication_id,
    'medication_regimen_id',v_regimen_id
  ));
end
$function$

CREATE OR REPLACE FUNCTION private.phms_complete_line_account_link_impl(p_verification_token text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_req public.account_link_requests%rowtype;
  v_identity public.line_identities%rowtype;
  v_hash text;
  v_line_account_id uuid;
  v_auth_account_id uuid;
  v_primary_user_id uuid;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  if p_verification_token is null or btrim(p_verification_token) = '' then
    raise exception 'verification_token_required';
  end if;

  if not exists (select 1 from public.profiles where id = v_uid) then
    raise exception 'profile_not_found';
  end if;

  v_hash := encode(digest(p_verification_token, 'sha256'), 'hex');

  select * into v_req
  from public.account_link_requests
  where verification_token_hash = v_hash
  for update;

  if not found then
    raise exception 'invalid_verification_token';
  end if;

  if v_req.status <> 'pending' then
    raise exception 'link_request_not_pending';
  end if;

  if v_req.expires_at is not null and v_req.expires_at <= now() then
    update public.account_link_requests
    set status='expired', updated_at=now()
    where id=v_req.id;
    raise exception 'link_request_expired';
  end if;

  select * into v_identity
  from public.line_identities
  where id = v_req.line_identity_id
  for update;

  if not found then
    raise exception 'line_identity_not_found';
  end if;

  if coalesce(v_identity.is_active,false) is not true then
    raise exception 'line_identity_inactive';
  end if;

  v_line_account_id := v_identity.account_id;

  if v_line_account_id is null and v_identity.user_id is not null then
    v_line_account_id := private.phms_ensure_account_for_user(
      v_identity.user_id,
      'legacy_line_anchor'
    );
  end if;

  select aau.account_id
  into v_auth_account_id
  from public.account_auth_users aau
  where aau.auth_user_id = v_uid
  limit 1;

  if v_line_account_id is null then
    if v_auth_account_id is null then
      v_auth_account_id := private.phms_ensure_account_for_user(v_uid,'login');
    end if;
    v_line_account_id := v_auth_account_id;
  elsif v_auth_account_id is not null
        and v_auth_account_id <> v_line_account_id then
    raise exception 'auth_user_already_linked_to_another_account';
  end if;

  if v_auth_account_id is null then
    insert into public.account_auth_users(
      account_id,auth_user_id,auth_kind,is_primary
    )
    values(
      v_line_account_id,v_uid,'linked_login',false
    )
    on conflict(auth_user_id) do nothing;
  end if;

  select a.primary_auth_user_id
  into v_primary_user_id
  from public.accounts a
  where a.id = v_line_account_id
    and a.status='active';

  if v_primary_user_id is null then
    raise exception 'account_not_active';
  end if;

  update public.line_identities
  set account_id=v_line_account_id,
      user_id=v_primary_user_id,
      updated_at=now()
  where id=v_identity.id;

  insert into public.line_login_accounts(
    line_user_id,auth_user_id,account_id,display_name,picture_url
  )
  values(
    v_identity.line_user_id,
    v_primary_user_id,
    v_line_account_id,
    v_identity.display_name,
    v_identity.picture_url
  )
  on conflict(line_user_id) do update
  set auth_user_id=excluded.auth_user_id,
      account_id=excluded.account_id,
      display_name=coalesce(excluded.display_name,public.line_login_accounts.display_name),
      picture_url=coalesce(excluded.picture_url,public.line_login_accounts.picture_url),
      updated_at=now();

  update public.account_link_requests
  set requested_user_id=v_uid,
      status='completed',
      confirmed_at=now(),
      completed_at=now(),
      updated_at=now()
  where id=v_req.id;

  insert into public.audit_logs(
    actor_user_id,target_user_id,event_type,resource,
    record_id,new_data,description
  ) values (
    v_uid,
    v_primary_user_id,
    'line_account_linked',
    'line_identity',
    v_identity.id,
    jsonb_build_object(
      'account_id',v_line_account_id,
      'line_identity_id',v_identity.id,
      'linked_auth_user_id',v_uid,
      'primary_auth_user_id',v_primary_user_id,
      'is_active',true
    ),
    'LINE identity linked to canonical PHMS account'
  );

  return query
  select v_identity.id,v_uid,'completed'::text;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_default_hospital_display_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
 v_name text;
 v_code text;
BEGIN
 IF nullif(btrim(coalesce(NEW.display_name,'')),'') IS NOT NULL THEN RETURN NEW; END IF;
 v_name:=nullif(btrim(coalesce(NEW.name,'')),'');
 IF v_name IS NULL THEN RETURN NEW; END IF;
 IF coalesce(NEW.organization_type,'hospital') <> 'hospital' THEN
   NEW.display_name:=v_name;
   RETURN NEW;
 END IF;
 v_code:=nullif(upper(btrim(coalesce(NEW.external_code,''))),'');
 IF v_code='LKB' THEN
   NEW.display_name:='รพ.นคราภิบาล (LKB)';
   RETURN NEW;
 END IF;
 v_name:=regexp_replace(v_name,'^โรงพยาบาล[[:space:]]*','','');
 v_name:=regexp_replace(v_name,'^รพ[.]?[[:space:]]*','','');
 NEW.display_name:='รพ.'||v_name;
 IF v_code IS NOT NULL AND position('('||v_code||')' IN upper(NEW.display_name))=0 THEN
   NEW.display_name:=NEW.display_name||' ('||v_code||')';
 END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION private.phms_enqueue_appointment_confirmed_notifications(p_appointment_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_appt public.appointments%rowtype;
  v_person public.persons%rowtype;
  v_rec record;
  v_group record;
  v_ack_id uuid;
  v_notification_id uuid;
  v_user_count int:=0;
  v_group_count int:=0;
  v_ack_count int:=0;
  v_person_name text;
  v_message text;
  v_date_text text;
  v_time_text text;
begin
  select * into v_appt
  from public.appointments
  where id=p_appointment_id and deleted_at is null;
  if not found then raise exception 'appointment_not_found'; end if;

  select * into v_person from public.persons where id=v_appt.person_id;
  v_person_name:=coalesce(
    nullif(btrim(v_person.display_name),''),
    nullif(btrim(concat_ws(' ',v_person.first_name,v_person.last_name)),''),
    'บุคคลในครอบครัว'
  );

  v_date_text:=to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','DD/MM/')||
    ((extract(year from v_appt.appointment_at at time zone 'Asia/Bangkok')::int)+543)::text;
  v_time_text:=to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','HH24:MI');

  v_message:=concat(
    '👤 ',v_person_name,
    E'\nนัดเพื่อ: ',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
    E'\n📆 วันนัด: ',v_date_text,
    E'\n🕐 เวลา: ',v_time_text,' น.',
    case when nullif(btrim(v_appt.hospital_name),'') is not null
      then E'\n🏥 สถานพยาบาล: '||v_appt.hospital_name else '' end,
    case when nullif(btrim(v_appt.department),'') is not null
      then E'\n🏢 แผนก/คลินิก: '||v_appt.department else '' end,
    case when nullif(btrim(v_appt.preparation_notes),'') is not null
      then E'\n🧾 เตรียมตัว: '||v_appt.preparation_notes else '' end
  );

  for v_rec in
    select r.recipient_user_id
    from private.phms_notification_recipients(v_appt.person_id,'appointments') r
  loop
    v_ack_id:=null;
    if v_person.linked_user_id is not null
       and v_rec.recipient_user_id=v_person.linked_user_id then
      insert into public.appointment_acknowledgements(
        appointment_id,user_id,ack_type,status,requested_by,requested_at,
        note,change_snapshot,created_at,updated_at
      ) values(
        v_appt.id,v_rec.recipient_user_id,'important_change','pending',
        p_actor_user_id,now(),'รับทราบนัดที่ยืนยันแล้ว',
        jsonb_build_object(
          'source','appointment_confirmed',
          'appointment_at',v_appt.appointment_at,
          'title',v_appt.title
        ),
        now(),now()
      )
      returning id into v_ack_id;
      v_ack_count:=v_ack_count+1;
    end if;

    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_appt.family_id,v_rec.recipient_user_id,v_appt.person_id,v_appt.family_person_id,
      'appointment_confirmed','📅 ยืนยันนัดหมายแล้ว',v_message,v_appt.id,
      'line','normal','pending',now(),now(),
      jsonb_strip_nulls(jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'appointment_at',v_appt.appointment_at,
        'require_ack',v_ack_id is not null,
        'ack_id',v_ack_id,
        'ack_code',case when v_ack_id is not null then substr(v_ack_id::text,1,12) end,
        'ack_type',case when v_ack_id is not null then 'important_change' end
      )),
      'appointment-confirmed:'||v_appt.id::text||':user:'||v_rec.recipient_user_id::text,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null
    do update set
      title=excluded.title,
      message=excluded.message,
      payload=excluded.payload,
      status='pending',
      scheduled_for=now(),
      next_attempt_at=now(),
      last_error=null,
      updated_at=now()
    returning id into v_notification_id;

    if v_ack_id is not null then
      update public.appointment_acknowledgements
      set notification_id=v_notification_id,updated_at=now()
      where id=v_ack_id;
    end if;
    v_user_count:=v_user_count+1;
  end loop;

  for v_group in
    select gt.id,gt.line_group_id
    from public.appointment_line_group_targets gt
    where gt.appointment_id=v_appt.id and gt.status='active'
  loop
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_appt.family_id,null,v_appt.person_id,v_appt.family_person_id,
      'appointment_confirmed_group','📅 ยืนยันนัดหมายแล้ว',v_message,v_appt.id,
      'line','normal','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'appointment_at',v_appt.appointment_at,
        'line_destination_type','group',
        'line_destination_id',v_group.line_group_id,
        'group_target_id',v_group.id
      ),
      'appointment-confirmed:'||v_appt.id::text||':group:'||v_group.id::text,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null
    do update set
      title=excluded.title,
      message=excluded.message,
      payload=excluded.payload,
      status='pending',
      scheduled_for=now(),
      next_attempt_at=now(),
      last_error=null,
      updated_at=now();
    v_group_count:=v_group_count+1;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'user_notifications',v_user_count,
    'group_notifications',v_group_count,
    'patient_ack_requests',v_ack_count
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_ensure_account_for_user(p_user_id uuid, p_auth_kind text DEFAULT 'login'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_account_id uuid;
  v_kind text;
begin
  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  if not exists (select 1 from public.profiles p where p.id = p_user_id) then
    raise exception 'profile_not_found';
  end if;

  select aau.account_id
  into v_account_id
  from public.account_auth_users aau
  where aau.auth_user_id = p_user_id
  limit 1;

  if v_account_id is not null then
    return v_account_id;
  end if;

  select a.id
  into v_account_id
  from public.accounts a
  where a.primary_auth_user_id = p_user_id
  limit 1;

  if v_account_id is null then
    insert into public.accounts(primary_auth_user_id)
    values (p_user_id)
    returning id into v_account_id;
  end if;

  v_kind := case
    when p_auth_kind in ('system_anchor','legacy_line_anchor','login','linked_login')
      then p_auth_kind
    else 'login'
  end;

  insert into public.account_auth_users(account_id, auth_user_id, auth_kind, is_primary)
  values (v_account_id, p_user_id, v_kind, true)
  on conflict (auth_user_id) do update
  set updated_at = now();

  update public.persons
  set linked_account_id = v_account_id,
      updated_at = now()
  where linked_user_id = p_user_id
    and linked_account_id is null;

  return v_account_id;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_find_record_request_for_line(p_line_user_id text, p_request_code text, p_action text DEFAULT 'view'::text)
 RETURNS TABLE(request_id uuid, episode_id uuid, actor_user_id uuid, family_id uuid, family_person_id uuid, person_id uuid, person_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ctx record;
  v_code text:=lower(btrim(coalesce(p_request_code,'')));
  v_count int;
  v_req public.medical_record_requests%rowtype;
begin
  if length(v_code)<8 then raise exception 'record_request_code_too_short'; end if;

  select * into v_ctx
  from private.phms_line_active_treatment_context(p_line_user_id,p_action)
  limit 1;

  select count(*) into v_count
  from public.medical_record_requests r
  where r.person_id=v_ctx.person_id
    and r.deleted_at is null
    and lower(r.id::text) like v_code||'%';

  if v_count=0 then raise exception 'record_request_not_found'; end if;
  if v_count>1 then raise exception 'record_request_code_ambiguous'; end if;

  select * into v_req
  from public.medical_record_requests r
  where r.person_id=v_ctx.person_id
    and r.deleted_at is null
    and lower(r.id::text) like v_code||'%'
  limit 1;

  return query
  select v_req.id,v_req.treatment_episode_id,v_ctx.actor_user_id,v_ctx.family_id,
         v_ctx.family_person_id,v_ctx.person_id,v_ctx.person_name;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_find_treatment_episode_for_line(p_line_user_id text, p_episode_code text, p_action text DEFAULT 'view'::text)
 RETURNS TABLE(episode_id uuid, actor_user_id uuid, family_id uuid, family_person_id uuid, person_id uuid, person_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ctx record;
  v_code text:=lower(btrim(coalesce(p_episode_code,'')));
  v_count int;
  v_episode_id uuid;
begin
  if length(v_code)<8 then raise exception 'episode_code_too_short'; end if;

  select * into v_ctx
  from private.phms_line_active_treatment_context(p_line_user_id,p_action)
  limit 1;

  select count(*)
  into v_count
  from public.treatment_episodes e
  where e.person_id=v_ctx.person_id
    and e.deleted_at is null
    and lower(e.id::text) like v_code||'%';

  if v_count=0 then raise exception 'treatment_episode_not_found'; end if;
  if v_count>1 then raise exception 'treatment_episode_code_ambiguous'; end if;

  select e.id
  into v_episode_id
  from public.treatment_episodes e
  where e.person_id=v_ctx.person_id
    and e.deleted_at is null
    and lower(e.id::text) like v_code||'%'
  limit 1;

  return query
  select v_episode_id,v_ctx.actor_user_id,v_ctx.family_id,v_ctx.family_person_id,
         v_ctx.person_id,v_ctx.person_name;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_guard_line_group_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
BEGIN
  IF new.channel_type IS DISTINCT FROM 'line_group' THEN RETURN new; END IF;
  IF new.setup_completed_at IS NOT NULL
     AND (new.last_completed_at IS NULL OR new.last_completed_at < new.setup_completed_at)
    THEN new.last_completed_at:=new.setup_completed_at; END IF;
  IF new.status IS DISTINCT FROM 'active' OR new.setup_completed_at IS NULL THEN
    new.can_receive_notifications:=false;
    new.can_query_bot:=false;
  ELSIF TG_OP='UPDATE' AND old.setup_completed_at IS NULL AND new.setup_completed_at IS NOT NULL THEN
    new.can_receive_notifications:=true;
  END IF;
  RETURN new;
END $function$

CREATE OR REPLACE FUNCTION private.phms_guard_terminal_linking_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_terminal boolean := false;
begin
  if tg_table_name = 'account_link_requests' then
    v_terminal := old.status in ('completed','rejected','expired','cancelled');
  elsif tg_table_name = 'person_claim_requests' then
    v_terminal := old.status in ('completed','rejected','expired','cancelled');
  elsif tg_table_name = 'person_claim_invitations' then
    v_terminal := old.status in ('accepted','revoked','expired');
  end if;

  if v_terminal and new.status is distinct from old.status then
    raise exception 'terminal_status_immutable';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.phms_guard_unique_person_card_color()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE v_family uuid;
BEGIN
 IF NEW.card_color IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.card_color IS NOT DISTINCT FROM OLD.card_color THEN RETURN NEW; END IF;
 NEW.card_color:=upper(NEW.card_color);
 FOR v_family IN SELECT DISTINCT family_id FROM public.family_persons WHERE person_id=NEW.person_id AND status='active' ORDER BY family_id LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family::text, 9017));
  IF EXISTS (
   SELECT 1 FROM public.family_persons a
   JOIN public.family_persons b ON b.family_id=a.family_id AND b.status='active' AND b.person_id<>a.person_id
   JOIN public.person_ui_preferences pref ON pref.person_id=b.person_id
   WHERE a.person_id=NEW.person_id AND a.status='active' AND a.family_id=v_family
     AND upper(pref.card_color)=NEW.card_color
  ) THEN RAISE EXCEPTION 'person_color_already_used_in_family' USING ERRCODE='23505'; END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.phms_healthcare_org_display_label_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
begin
 if new.organization_type='hospital' then
  if new.display_name is null or btrim(new.display_name)='' then
   new.display_name:=private.phms_hospital_auto_display_name(new.name,new.external_code);
  elsif tg_op='UPDATE' then
   if (new.name is distinct from old.name or new.external_code is distinct from old.external_code)
       and new.display_name is not distinct from old.display_name
       and old.display_name is not distinct from private.phms_hospital_auto_display_name(old.name,old.external_code) then
    new.display_name:=private.phms_hospital_auto_display_name(new.name,new.external_code);
   end if;
  end if;
 end if;
 return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_hospital_display_short(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v text:=nullif(btrim(coalesce(p_value,'')),'');
 c text; v_display text;
begin
 if v IS NULL then return null; end if;
 c:=private.phms_canonical_hospital_code(v);
 IF c IS NOT NULL THEN
   SELECT nullif(btrim(o.display_name),'') INTO v_display
   FROM public.healthcare_organizations o
   WHERE o.deleted_at IS NULL AND upper(coalesce(o.external_code,''))=c
   ORDER BY o.updated_at DESC LIMIT 1;
   IF v_display IS NOT NULL THEN RETURN v_display; END IF;
 END IF;
 IF v ~ '^โรงพยาบาล' THEN RETURN regexp_replace(v,'^โรงพยาบาล[[:space:]]*','รพ.'); END IF;
 RETURN v;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_inherit_intake_restart_intent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_old_id uuid;
  v_old_meta jsonb;
begin
  begin
    v_old_id:=(new.source_metadata->>'restarted_from_source_id')::uuid;
  exception when others then
    v_old_id:=null;
  end;

  if v_old_id is null then
    return new;
  end if;

  select source_metadata into v_old_meta
  from public.data_intake_sources
  where id=v_old_id;

  if v_old_meta is null then
    return new;
  end if;

  new.source_metadata:=coalesce(new.source_metadata,'{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'intent_resource',nullif(v_old_meta->>'intent_resource',''),
      'intent_mode',nullif(v_old_meta->>'intent_mode',''),
      'intent_started_from',nullif(v_old_meta->>'intent_started_from','')
    ));
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_intake_candidate_signature(p_candidate_type text, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'private', 'public', 'extensions'
AS $function$
declare
  v_type text := lower(coalesce(p_candidate_type,''));
  v_data jsonb := coalesce(p_data,'{}'::jsonb);
  v_structured boolean := false;
  v_sig text;
begin
  if v_type='appointment' then
    v_structured :=
      coalesce(v_data->>'appointment_at','')<>'' or
      coalesce(v_data->>'date_text','')<>'' or
      coalesce(v_data->>'time_text','')<>'' or
      coalesce(v_data->>'hospital_name','')<>'' or
      coalesce(v_data->>'department','')<>'' or
      coalesce(v_data->>'doctor_name','')<>'' or
      coalesce(v_data->>'title','')<>'';

    if v_structured then
      v_sig := concat_ws('|',
        'appointment',
        private.phms_normalize_dedupe_text(v_data->>'appointment_at'),
        private.phms_normalize_dedupe_text(v_data->>'date_text'),
        private.phms_normalize_dedupe_text(v_data->>'time_text'),
        private.phms_normalize_dedupe_text(v_data->>'hospital_name'),
        private.phms_normalize_dedupe_text(v_data->>'department'),
        private.phms_normalize_dedupe_text(v_data->>'doctor_name'),
        private.phms_normalize_dedupe_text(v_data->>'title'),
        private.phms_normalize_dedupe_text(v_data->>'external_reference')
      );
    else
      v_sig := concat_ws('|','appointment',
        private.phms_normalize_dedupe_text(
          coalesce(v_data->>'source_text',v_data->>'text_preview',v_data::text)
        )
      );
    end if;

  elsif v_type='medication' then
    v_structured :=
      coalesce(v_data->>'medication_id','')<>'' or
      coalesce(v_data->>'normalized_key','')<>'' or
      coalesce(v_data->>'generic_name','')<>'' or
      coalesce(v_data->>'brand_name','')<>'' or
      coalesce(v_data->>'strength_value','')<>'' or
      coalesce(v_data->>'strength_text','')<>'' or
      coalesce(v_data->>'dose_text','')<>'' or
      coalesce(v_data->>'instructions','')<>'';

    if v_structured then
      v_sig := concat_ws('|',
        'medication',
        private.phms_normalize_dedupe_text(v_data->>'medication_id'),
        private.phms_normalize_dedupe_text(v_data->>'normalized_key'),
        private.phms_normalize_dedupe_text(v_data->>'generic_name'),
        private.phms_normalize_dedupe_text(v_data->>'brand_name'),
        private.phms_normalize_dedupe_text(v_data->>'strength_value'),
        private.phms_normalize_dedupe_text(v_data->>'strength_unit'),
        private.phms_normalize_dedupe_text(v_data->>'strength_text'),
        private.phms_normalize_dedupe_text(v_data->>'dose_text'),
        private.phms_normalize_dedupe_text(v_data->>'frequency_text'),
        private.phms_normalize_dedupe_text(v_data->>'route'),
        private.phms_normalize_dedupe_text(v_data->>'instructions')
      );
    else
      v_sig := concat_ws('|','medication',
        private.phms_normalize_dedupe_text(
          coalesce(v_data->>'source_text',v_data->>'text_preview',v_data::text)
        )
      );
    end if;

  elsif v_type in ('health_measurement','measurement') then
    v_sig := concat_ws('|',
      'health_measurement',
      private.phms_normalize_dedupe_text(v_data->>'measurement_type'),
      private.phms_normalize_dedupe_text(v_data->>'measured_at'),
      private.phms_normalize_dedupe_text(v_data->>'value_numeric'),
      private.phms_normalize_dedupe_text(v_data->>'value_text'),
      private.phms_normalize_dedupe_text(v_data->>'systolic'),
      private.phms_normalize_dedupe_text(v_data->>'diastolic'),
      private.phms_normalize_dedupe_text(v_data->>'unit')
    );

  else
    v_structured :=
      coalesce(v_data->>'document_type','')<>'' or
      coalesce(v_data->>'document_date','')<>'' or
      coalesce(v_data->>'title','')<>'';

    if v_structured then
      v_sig := concat_ws('|',
        v_type,
        private.phms_normalize_dedupe_text(v_data->>'document_type'),
        private.phms_normalize_dedupe_text(v_data->>'document_date'),
        private.phms_normalize_dedupe_text(v_data->>'title'),
        private.phms_normalize_dedupe_text(
          coalesce(v_data->>'canonical_key',v_data->>'source_text',v_data->>'text_preview','')
        )
      );
    else
      v_sig := concat_ws('|',v_type,
        private.phms_normalize_dedupe_text(
          coalesce(v_data->>'canonical_key',v_data->>'source_text',v_data->>'text_preview',v_data::text)
        )
      );
    end if;
  end if;

  return v_sig;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_jsonb_time_array(p_value jsonb)
 RETURNS time without time zone[]
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'private', 'public'
AS $function$
declare
  v_out time[] := array[]::time[];
  v_text text;
begin
  if jsonb_typeof(coalesce(p_value,'null'::jsonb))<>'array' then
    return null;
  end if;
  for v_text in select jsonb_array_elements_text(p_value)
  loop
    begin
      v_out := array_append(v_out,v_text::time);
    exception when others then
      raise exception 'invalid_exact_time:%',v_text;
    end;
  end loop;
  return v_out;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_active_treatment_context(p_line_user_id text, p_action text DEFAULT 'view'::text)
 RETURNS TABLE(actor_user_id uuid, family_id uuid, family_person_id uuid, person_id uuid, person_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_action text:=lower(btrim(coalesce(p_action,'view')));
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);

  select c.* into v_ctx
  from private.line_identity_contexts c
  where c.line_identity_id=v_line.line_identity_id;

  if v_ctx.active_family_id is null or v_ctx.active_family_person_id is null then
    raise exception 'active_family_person_required';
  end if;

  select fp.* into v_fp
  from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id
    and fp.family_id=v_ctx.active_family_id
    and coalesce(fp.status,'active')='active';

  if not found then raise exception 'active_family_person_not_found'; end if;

  if v_action='update' then
    if not (
      private.user_can_access_family_person(v_line.user_id,v_fp.id,'health_data','update')
      or private.user_can_access_family_person(v_line.user_id,v_fp.id,'appointments','update')
    ) then
      raise exception 'treatment_history_update_required';
    end if;
  else
    if not (
      private.user_can_access_family_person(v_line.user_id,v_fp.id,'health_data','view')
      or private.user_can_access_family_person(v_line.user_id,v_fp.id,'appointments','view')
    ) then
      raise exception 'treatment_history_view_required';
    end if;
  end if;

  return query
  select
    v_line.user_id,
    v_ctx.active_family_id,
    v_fp.id,
    v_fp.person_id,
    private.family_person_label_for_viewer(v_line.user_id,v_fp.id);
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_appointment_access(p_line_user_id text, p_record_code text)
 RETURNS TABLE(resource_key text, record_id uuid, actor_user_id uuid, target_person_id uuid, target_person_name text, active_family_id uuid, active_family_person_id uuid, has_person_view boolean, can_update boolean, is_assignee boolean, full_access boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_code text:=lower(btrim(coalesce(p_record_code,'')));
  v_count integer:=0;
  v_id uuid;
  v_a public.appointments%rowtype;
  v_fp_id uuid;
  v_has_view boolean:=false;
  v_can_update boolean:=false;
  v_is_assignee boolean:=false;
  v_person_name text;
begin
  if length(v_code)<8 then raise exception 'record_code_too_short'; end if;

  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  if v_line.user_id is null then raise exception 'line_identity_not_ready'; end if;

  select count(*)::int
  into v_count
  from public.appointments a
  left join public.family_persons fp on fp.id=a.family_person_id
  where lower(a.id::text) like v_code||'%'
    and a.deleted_at is null
    and (
      (
        fp.id is not null
        and coalesce(fp.status,'active')='active'
        and private.user_can_access_family_person(
          v_line.user_id,fp.id,'appointments','view'
        )
      )
      or exists(
        select 1
        from public.appointment_assignees aa
        where aa.appointment_id=a.id
          and aa.user_id=v_line.user_id
          and aa.status in ('assigned','accepted')
      )
    );

  if v_count=0 then raise exception 'appointment_not_found_or_not_accessible'; end if;
  if v_count>1 then raise exception 'appointment_code_ambiguous'; end if;

  select a.id
  into v_id
  from public.appointments a
  left join public.family_persons fp on fp.id=a.family_person_id
  where lower(a.id::text) like v_code||'%'
    and a.deleted_at is null
    and (
      (
        fp.id is not null
        and coalesce(fp.status,'active')='active'
        and private.user_can_access_family_person(
          v_line.user_id,fp.id,'appointments','view'
        )
      )
      or exists(
        select 1
        from public.appointment_assignees aa
        where aa.appointment_id=a.id
          and aa.user_id=v_line.user_id
          and aa.status in ('assigned','accepted')
      )
    )
  order by a.id::text
  limit 1;

  select * into v_a
  from public.appointments
  where id=v_id and deleted_at is null;

  v_fp_id:=v_a.family_person_id;
  if v_fp_id is null then
    select fp.id into v_fp_id
    from public.family_persons fp
    where fp.family_id=v_a.family_id
      and fp.person_id=v_a.person_id
      and coalesce(fp.status,'active')='active'
    order by fp.created_at
    limit 1;
  end if;

  if v_fp_id is not null then
    v_has_view:=private.user_can_access_family_person(
      v_line.user_id,v_fp_id,'appointments','view'
    );
    v_can_update:=private.user_can_access_family_person(
      v_line.user_id,v_fp_id,'appointments','update'
    );
  end if;

  select exists(
    select 1
    from public.appointment_assignees aa
    where aa.appointment_id=v_a.id
      and aa.user_id=v_line.user_id
      and aa.status in ('assigned','accepted')
  ) into v_is_assignee;

  if v_fp_id is not null then
    v_person_name:=private.phms_notification_person_label(
      v_line.user_id,v_a.person_id,v_fp_id
    );
  else
    v_person_name:=private.phms_group_person_label(
      v_a.person_id,v_a.family_person_id
    );
  end if;

  return query select
    'appointment'::text,
    v_a.id,
    v_line.user_id,
    v_a.person_id,
    coalesce(nullif(btrim(v_person_name),''),'ผู้ป่วย'),
    v_a.family_id,
    v_fp_id,
    v_has_view,
    v_can_update,
    v_is_assignee,
    (v_can_update or v_is_assignee);
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_appointment_sensitive_access(p_line_user_id text, p_record_code text)
 RETURNS TABLE(actor_user_id uuid, record_id uuid, family_person_id uuid, is_self boolean, is_primary boolean, is_care_assistant boolean, can_view_sensitive boolean, can_update_appointments boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_access record;
  v_linked_user uuid;
  v_self boolean:=false;
  v_primary boolean:=false;
  v_helper boolean:=false;
  v_update boolean:=false;
  v_view_finance boolean:=false;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  select * into v_access
  from private.phms_line_appointment_access(
    p_line_user_id,p_record_code
  )
  limit 1;

  select p.linked_user_id into v_linked_user
  from public.persons p
  where p.id=v_access.target_person_id;

  v_self:=v_linked_user=v_line.user_id;
  v_primary:=case
    when v_access.active_family_person_id is null then false
    else private.phms_is_medical_primary(
      v_line.user_id,v_access.active_family_person_id
    )
  end;

  select exists(
    select 1
    from public.appointment_assignees aa
    where aa.appointment_id=v_access.record_id
      and aa.user_id=v_line.user_id
      and aa.assignment_role='caregiver'
      and aa.status in ('assigned','accepted')
      and v_access.active_family_person_id is not null
      and private.user_can_access_family_person(
        v_line.user_id,
        v_access.active_family_person_id,
        'appointments','view'
      )
  ) into v_helper;

  v_view_finance:=v_access.active_family_person_id is not null
    and private.user_can_access_family_person(v_line.user_id,v_access.active_family_person_id,'expenses','view');

  if v_access.active_family_person_id is not null then
    v_update:=private.user_can_access_family_person(
      v_line.user_id,
      v_access.active_family_person_id,
      'expenses','update'
    );
  end if;

  return query select
    v_line.user_id,
    v_access.record_id,
    v_access.active_family_person_id,
    v_self,
    v_primary,
    v_helper,
    v_view_finance,
    (v_view_finance and v_update);
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_can_manage_healthcare_master(p_line_user_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  if v_line.user_id is null then return false; end if;

  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);

  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_family_id is not null then
    return exists(
      select 1
      from public.family_role_assignments r
      where r.family_id=v_ctx.active_family_id
        and r.user_id=v_line.user_id
        and r.status='active'
        and r.role in ('owner','admin')
    );
  end if;

  return exists(
    select 1
    from public.family_role_assignments r
    where r.user_id=v_line.user_id
      and r.status='active'
      and r.role in ('owner','admin')
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_crud_context(p_line_user_id text, p_resource text, p_action text)
 RETURNS TABLE(actor_user_id uuid, target_person_id uuid, target_person_name text, active_family_id uuid, active_family_person_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_perm text:=private.phms_crud_permission_resource(p_resource);
  v_ctx record;
begin
  if v_perm is null then raise exception 'invalid_crud_resource'; end if;
  if p_action not in ('view','create','update','delete') then raise exception 'invalid_crud_action'; end if;

  select * into v_ctx
  from public.phms_resolve_line_command_context(
    p_line_user_id,v_perm,p_action,true,'any'
  )
  limit 1;

  if not found then raise exception 'crud_context_not_found'; end if;
  if coalesce(v_ctx.context_ready,false) is not true then
    raise exception 'crud_context_not_ready:%',coalesce(v_ctx.resolution_code,'unknown');
  end if;
  if coalesce(v_ctx.permission_granted,false) is not true then
    raise exception 'crud_permission_denied:%:%',v_perm,p_action;
  end if;
  if v_ctx.target_person_id is null then raise exception 'crud_person_required'; end if;

  return query select
    v_ctx.user_id,
    v_ctx.target_person_id,
    v_ctx.target_person_name,
    v_ctx.active_family_id,
    v_ctx.active_family_person_id;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_crud_stop_core(p_line_user_id text, p_resource text, p_record_code text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_old jsonb;
  v_new jsonb;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,p_resource,p_record_code,'delete'
  )
  limit 1;

  if v_ref.resource_key='medication' then
    select to_jsonb(pm) into v_old from public.person_medications pm where pm.id=v_ref.record_id;

    update public.person_medications
    set status='discontinued',
        end_date=coalesce(end_date,current_date),
        updated_at=now()
    where id=v_ref.record_id;

    update public.medication_regimens
    set is_current=false,
        effective_to=coalesce(effective_to,now()),
        updated_at=now()
    where person_medication_id=v_ref.record_id
      and deleted_at is null
      and is_current=true;

    select to_jsonb(pm) into v_new from public.person_medications pm where pm.id=v_ref.record_id;

    insert into public.medication_change_history(
      person_medication_id,change_type,old_data,new_data,reason,effective_at,changed_by
    ) values(
      v_ref.record_id,'stopped',v_old,v_new,
      coalesce(nullif(btrim(p_reason),''),'line_crud_stop'),now(),v_ref.actor_user_id
    );

  elsif v_ref.resource_key='appointment' then
    select to_jsonb(a) into v_old from public.appointments a where a.id=v_ref.record_id;
    update public.appointments
    set status='cancelled',updated_at=now()
    where id=v_ref.record_id;
    select to_jsonb(a) into v_new from public.appointments a where a.id=v_ref.record_id;

  elsif v_ref.resource_key='health' then
    select to_jsonb(h) into v_old from public.health_measurements h where h.id=v_ref.record_id;
    update public.health_measurements
    set deleted_at=now()
    where id=v_ref.record_id;
    select to_jsonb(h) into v_new from public.health_measurements h where h.id=v_ref.record_id;

  else
    select to_jsonb(d) into v_old from public.medical_documents d where d.id=v_ref.record_id;
    update public.medical_documents
    set deleted_at=now(),updated_at=now()
    where id=v_ref.record_id;
    select to_jsonb(d) into v_new from public.medical_documents d where d.id=v_ref.record_id;
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'crud_stop',v_ref.resource_key,v_ref.record_id,
    v_old,v_new,coalesce(nullif(btrim(p_reason),''),'LINE CRUD stop')
  );

  return jsonb_build_object(
    'ok',true,'resource',v_ref.resource_key,
    'record_id',v_ref.record_id,'record_code',substr(v_ref.record_id::text,1,12),
    'stopped',true,'item',v_new
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_line_crud_update_core(p_line_user_id text, p_resource text, p_record_code text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_old jsonb;
  v_new jsonb;
  v_reg public.medication_regimens%rowtype;
  v_has_reg_patch boolean;
  v_status text;
begin
  if p_patch is null or jsonb_typeof(p_patch)<>'object' then
    raise exception 'crud_patch_object_required';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,p_resource,p_record_code,'update'
  )
  limit 1;

  if v_ref.resource_key='medication' then
    select to_jsonb(pm) into v_old
    from public.person_medications pm where pm.id=v_ref.record_id;

    if p_patch ? 'status' then
      v_status:=lower(coalesce(p_patch->>'status',''));
      if v_status not in ('regular','prn','paused') then
        raise exception 'invalid_medication_edit_status';
      end if;
    end if;

    update public.person_medications
    set indication=case when p_patch?'indication' then nullif(btrim(p_patch->>'indication'),'') else indication end,
        notes=case when p_patch?'notes' then nullif(btrim(p_patch->>'notes'),'') else notes end,
        status=case when p_patch?'status' then v_status else status end,
        start_date=case when p_patch?'start_date' then private.phms_try_date(p_patch->>'start_date') else start_date end,
        updated_at=now()
    where id=v_ref.record_id;

    select * into v_reg
    from public.medication_regimens
    where person_medication_id=v_ref.record_id
      and deleted_at is null
      and is_current=true
    order by effective_from desc,created_at desc
    limit 1;

    v_has_reg_patch :=
      p_patch ?| array[
        'dose_value','dose_unit','dose_text','frequency_type','frequency_value',
        'frequency_unit','route','meal_relation','instructions','time_of_day','exact_times'
      ];

    if v_has_reg_patch and v_reg.id is null then
      insert into public.medication_regimens(
        person_medication_id,effective_from,is_current,created_by
      )
      values(v_ref.record_id,now(),true,v_ref.actor_user_id)
      returning * into v_reg;
    end if;

    if v_has_reg_patch then
      update public.medication_regimens
      set dose_value=case when p_patch?'dose_value' then private.phms_try_numeric(p_patch->>'dose_value') else dose_value end,
          dose_unit=case when p_patch?'dose_unit' then nullif(btrim(p_patch->>'dose_unit'),'') else dose_unit end,
          dose_text=case when p_patch?'dose_text' then nullif(btrim(p_patch->>'dose_text'),'') else dose_text end,
          frequency_type=case when p_patch?'frequency_type' then nullif(btrim(p_patch->>'frequency_type'),'') else frequency_type end,
          frequency_value=case when p_patch?'frequency_value' then private.phms_try_numeric(p_patch->>'frequency_value') else frequency_value end,
          frequency_unit=case when p_patch?'frequency_unit' then nullif(btrim(p_patch->>'frequency_unit'),'') else frequency_unit end,
          route=case when p_patch?'route' then nullif(btrim(p_patch->>'route'),'') else route end,
          meal_relation=case when p_patch?'meal_relation' then nullif(btrim(p_patch->>'meal_relation'),'') else meal_relation end,
          instructions=case when p_patch?'instructions' then nullif(btrim(p_patch->>'instructions'),'') else instructions end,
          time_of_day=case when p_patch?'time_of_day' then private.phms_jsonb_text_array(p_patch->'time_of_day') else time_of_day end,
          exact_times=case when p_patch?'exact_times' then private.phms_jsonb_time_array(p_patch->'exact_times') else exact_times end,
          updated_at=now()
      where id=v_reg.id;
    end if;

    select jsonb_build_object(
      'person_medication',to_jsonb(pm),
      'regimen',case when r.id is null then null else to_jsonb(r) end
    ) into v_new
    from public.person_medications pm
    left join lateral (
      select rr.* from public.medication_regimens rr
      where rr.person_medication_id=pm.id
        and rr.deleted_at is null and rr.is_current=true
      order by rr.effective_from desc,rr.created_at desc limit 1
    ) r on true
    where pm.id=v_ref.record_id;

    insert into public.medication_change_history(
      person_medication_id,change_type,old_data,new_data,reason,effective_at,changed_by
    ) values(
      v_ref.record_id,'updated',v_old,v_new,'line_crud_update',now(),v_ref.actor_user_id
    );

  elsif v_ref.resource_key='appointment' then
    select to_jsonb(a) into v_old from public.appointments a where a.id=v_ref.record_id;

    if p_patch?'appointment_at'
       and private.phms_try_timestamptz(p_patch->>'appointment_at') is null then
      raise exception 'invalid_appointment_at';
    end if;

    update public.appointments
    set title=case when p_patch?'title' then nullif(btrim(p_patch->>'title'),'') else title end,
        hospital_name=case when p_patch?'hospital_name' then nullif(btrim(p_patch->>'hospital_name'),'') else hospital_name end,
        department=case when p_patch?'department' then nullif(btrim(p_patch->>'department'),'') else department end,
        doctor_name=case when p_patch?'doctor_name' then nullif(btrim(p_patch->>'doctor_name'),'') else doctor_name end,
        appointment_at=case when p_patch?'appointment_at' then private.phms_try_timestamptz(p_patch->>'appointment_at') else appointment_at end,
        note=case when p_patch?'note' then nullif(btrim(p_patch->>'note'),'') else note end,
        appointment_type=case when p_patch?'appointment_type' then nullif(btrim(p_patch->>'appointment_type'),'') else appointment_type end,
        status=case
          when p_patch?'status' and lower(p_patch->>'status') in ('scheduled','completed')
            then lower(p_patch->>'status')
          else status end,
        updated_at=now()
    where id=v_ref.record_id;

    select to_jsonb(a) into v_new from public.appointments a where a.id=v_ref.record_id;

  elsif v_ref.resource_key='health' then
    select to_jsonb(h) into v_old from public.health_measurements h where h.id=v_ref.record_id;

    if p_patch?'measured_at'
       and private.phms_try_timestamptz(p_patch->>'measured_at') is null then
      raise exception 'invalid_measured_at';
    end if;

    update public.health_measurements
    set measurement_type=case when p_patch?'measurement_type' then nullif(private.phms_normalize_dedupe_text(p_patch->>'measurement_type'),'') else measurement_type end,
        measured_at=case when p_patch?'measured_at' then private.phms_try_timestamptz(p_patch->>'measured_at') else measured_at end,
        value_numeric=case when p_patch?'value_numeric' then private.phms_try_numeric(p_patch->>'value_numeric') else value_numeric end,
        value_text=case when p_patch?'value_text' then nullif(btrim(p_patch->>'value_text'),'') else value_text end,
        unit=case when p_patch?'unit' then nullif(btrim(p_patch->>'unit'),'') else unit end,
        systolic=case when p_patch?'systolic' then private.phms_try_numeric(p_patch->>'systolic') else systolic end,
        diastolic=case when p_patch?'diastolic' then private.phms_try_numeric(p_patch->>'diastolic') else diastolic end,
        context=case when p_patch?'context' then nullif(btrim(p_patch->>'context'),'') else context end,
        notes=case when p_patch?'notes' then nullif(btrim(p_patch->>'notes'),'') else notes end
    where id=v_ref.record_id;

    if exists(
      select 1 from public.health_measurements h
      where h.id=v_ref.record_id
        and h.value_numeric is null and h.value_text is null
        and h.systolic is null and h.diastolic is null
    ) then
      raise exception 'measurement_value_required';
    end if;

    if exists(
      select 1 from public.health_measurements h
      where h.id=v_ref.record_id
        and ((h.systolic is null) <> (h.diastolic is null))
    ) then
      raise exception 'blood_pressure_requires_systolic_and_diastolic';
    end if;

    select to_jsonb(h) into v_new from public.health_measurements h where h.id=v_ref.record_id;

  else
    select to_jsonb(d) into v_old from public.medical_documents d where d.id=v_ref.record_id;

    update public.medical_documents
    set title=case when p_patch?'title' then nullif(btrim(p_patch->>'title'),'') else title end,
        document_type=case when p_patch?'document_type' then coalesce(nullif(btrim(p_patch->>'document_type'),''),document_type) else document_type end,
        document_date=case when p_patch?'document_date' then private.phms_try_date(p_patch->>'document_date') else document_date end,
        updated_at=now()
    where id=v_ref.record_id;

    select to_jsonb(d) into v_new from public.medical_documents d where d.id=v_ref.record_id;
  end if;

  if v_ref.resource_key<>'medication' then
    insert into public.audit_logs(
      family_id,actor_user_id,family_person_id,event_type,resource,record_id,
      old_data,new_data,description
    )
    values(
      v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
      'crud_update',v_ref.resource_key,v_ref.record_id,
      v_old,v_new,'LINE CRUD update'
    );
  else
    insert into public.audit_logs(
      family_id,actor_user_id,family_person_id,event_type,resource,record_id,
      old_data,new_data,description
    )
    values(
      v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
      'crud_update','medication',v_ref.record_id,
      v_old,v_new,'LINE medication update'
    );
  end if;

  return jsonb_build_object(
    'ok',true,'resource',v_ref.resource_key,
    'record_id',v_ref.record_id,'record_code',substr(v_ref.record_id::text,1,12),
    'updated',true,'item',v_new
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_link_appointment_document_from_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_appt uuid;
  v_asset uuid;
  v_person uuid;
  v_doc_person uuid;
  v_kind text;
begin
  if new.resource_type<>'medical_documents' or new.source_record_id is null then
    return new;
  end if;

  select
    private.phms_try_uuid(s.source_metadata->>'appointment_id'),
    coalesce(s.storage_asset_id,new.source_storage_asset_id),
    lower(coalesce(nullif(s.source_metadata->>'appointment_link_kind',''),'result'))
  into v_appt,v_asset,v_kind
  from public.data_intake_candidates c
  join public.data_intake_sources s on s.id=c.source_id
  where c.id=new.source_record_id
  limit 1;

  if v_appt is null then return new; end if;
  if v_kind not in ('source','preparation','result','certificate','referral','other') then
    v_kind:='result';
  end if;

  select person_id into v_person from public.appointments where id=v_appt;
  select person_id into v_doc_person from public.medical_documents where id=new.record_id;
  if v_person is null or v_doc_person is distinct from v_person then
    return new;
  end if;

  insert into public.appointment_document_links(
    appointment_id,medical_document_id,storage_asset_id,link_kind,created_by
  )
  values(v_appt,new.record_id,v_asset,v_kind,new.created_by)
  on conflict do nothing;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_link_appointment_resource_from_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_appt uuid;
  v_person uuid;
  v_record_person uuid;
  v_relationship text;
begin
  if new.resource_type not in ('person_medications','health_measurements')
     or new.source_record_id is null then
    return new;
  end if;

  select
    private.phms_try_uuid(c.normalized_data->>'source_appointment_id'),
    coalesce(nullif(c.normalized_data->>'appointment_relationship',''),
      case when new.resource_type='person_medications' then 'changed_at_visit' else 'measured_at_visit' end)
  into v_appt,v_relationship
  from public.data_intake_candidates c
  where c.id=new.source_record_id
  limit 1;

  if v_appt is null then return new; end if;

  select person_id into v_person
  from public.appointments where id=v_appt;

  if new.resource_type='person_medications' then
    select person_id into v_record_person
    from public.person_medications where id=new.record_id;
  elsif new.resource_type='health_measurements' then
    select person_id into v_record_person
    from public.health_measurements where id=new.record_id;
  end if;

  if v_person is null or v_record_person is distinct from v_person then
    return new;
  end if;

  if v_relationship not in ('resulted_from_visit','changed_at_visit','measured_at_visit','measured_before_appointment','other') then
    v_relationship:='resulted_from_visit';
  end if;

  insert into public.appointment_resource_links(
    appointment_id,resource_type,record_id,relationship,created_by
  )
  values(v_appt,new.resource_type,new.record_id,v_relationship,new.created_by)
  on conflict do nothing;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_mark_walkin_time_known()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_catalog'
AS $function$
begin
 if old.visit_time_known=false and new.appointment_at is not null then
  new.visit_time_known:=true;
  new.planned_visit_date:=(new.appointment_at at time zone 'Asia/Bangkok')::date;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.phms_normalize_appointment_department(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_text text;
  v_norm text;
begin
  v_text:=nullif(btrim(regexp_replace(coalesce(p_value,''),'[[:space:]]+',' ','g')),'');
  if v_text is null then return null; end if;

  v_text:=regexp_replace(v_text,'^(แผนก|คลินิก)[[:space:]]*','','i');
  v_text:=nullif(btrim(v_text),'');
  if v_text is null then return null; end if;

  v_norm:=regexp_replace(lower(v_text),'[^0-9a-zก-๙]+','','g');

  if v_norm = any(array[
      'oph','opdoph','ophthalmology','ophthalmologic',
      'จักษุ','จักษุวิทยา','ตา','ต้อ','ต้อหิน'
     ]::text[])
     or v_norm like '%ophthalmolog%' then
    return 'จักษุ (OPD-OPH)';
  end if;

  if v_norm = any(array[
      'uro','opduro','urology','urologic','urological',
      'ปัสสาวะ','ฉี่'
     ]::text[])
     or v_norm like '%urolog%'
     or v_text ~* '(ศัลยกรรม.*(ทางเดินปัสสาวะ|ระบบทางเดินปัสสาวะ|ปัสสาวะ)|((ทางเดินปัสสาวะ|ระบบทางเดินปัสสาวะ|ปัสสาวะ).*)ศัลยกรรม|ยูโร)' then
    return 'ศัลยกรรมระบบทางเดินปัสสาวะ (OPD-URO)';
  end if;

  if v_norm = any(array[
      'ortho','opdortho','orthopedic','orthopaedic','orthopedics','orthopaedics',
      'กระดูก','ปวดเข่า','ปาดเข่า'
     ]::text[])
     or v_norm like '%orthopedic%'
     or v_norm like '%orthopaedic%'
     or v_text ~* '(ศัลยกรรมกระดูกและข้อ|กระดูกและข้อ|ออร์โธ)' then
    return 'ศัลยกรรมกระดูกและข้อ (OPD-ORTHO)';
  end if;

  return v_text;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_normalize_appointment_hospital_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_org uuid;
begin
  new.hospital_name:=private.phms_canonical_hospital_display(new.hospital_name);
  if new.hospital_name is null then
    new.organization_id:=null;
    new.hospital_hn:=null;
    return new;
  end if;

  v_org:=private.phms_canonical_hospital_org_id(new.hospital_name);
  if v_org is not null then
    new.organization_id:=v_org;
  end if;

  if tg_op='INSERT' then
    if nullif(btrim(coalesce(new.hospital_hn,'')),'') is null then
      new.hospital_hn:=private.phms_person_hospital_hn(
        new.person_id,new.organization_id,new.hospital_name
      );
    end if;
  else
    if (
      old.hospital_name is distinct from new.hospital_name
      or old.organization_id is distinct from new.organization_id
      or old.person_id is distinct from new.person_id
    ) and new.hospital_hn is not distinct from old.hospital_hn then
      new.hospital_hn:=private.phms_person_hospital_hn(
        new.person_id,new.organization_id,new.hospital_name
      );
    end if;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_person_color_unique_in_family()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f uuid; clash boolean;
BEGIN
 IF NEW.card_color IS NULL THEN RETURN NEW; END IF;
 NEW.card_color := upper(btrim(NEW.card_color));
 IF NEW.card_color !~ '^#[0-9A-F]{6}$' THEN RAISE EXCEPTION 'invalid_hex_color'; END IF;
 FOR f IN SELECT family_id FROM public.family_persons WHERE person_id=NEW.person_id AND status='active' ORDER BY family_id LOOP
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(f::text)::bigint);
  SELECT EXISTS(SELECT 1 FROM public.family_persons other
   JOIN public.person_ui_preferences ui ON ui.person_id=other.person_id
   WHERE other.family_id=f AND other.status='active' AND other.person_id<>NEW.person_id
     AND upper(ui.card_color)=NEW.card_color) INTO clash;
  IF clash THEN RAISE EXCEPTION 'person_color_already_used_in_family' USING ERRCODE='23505'; END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.phms_propose_owner_transfer(p_family uuid, p_new_owner uuid, p_old_role text, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
 if p_actor is null or p_actor=p_new_owner then raise exception 'invalid_owner_transfer';end if;
 if p_old_role not in ('member','admin') then raise exception 'invalid_previous_owner_role';end if;
 if not private.user_has_family_role(p_actor,p_family,array['owner']) then raise exception 'owner_only';end if;
 if not exists(select 1 from public.family_memberships fm where fm.family_id=p_family and fm.user_id=p_new_owner and fm.status='active') then raise exception 'target_not_active_member';end if;
 insert into private.household_owner_transfer_requests(family_id,current_owner_user_id,proposed_owner_user_id,previous_owner_role)
 values(p_family,p_actor,p_new_owner,p_old_role) returning id into v_id;
 insert into public.notifications(family_id,recipient_user_id,event_type,title,message,channel,priority,status,payload,dedupe_key)
 values(p_family,p_new_owner,'owner_transfer_invitation','🏡 มีคำขอให้เป็นเจ้าบ้าน','มีคนขอส่งต่อหน้าที่เจ้าบ้านให้คุณ กรุณาเปิดอิ่มอุ่น แล้วพิมพ์ “คำขอบ้าน” เพื่อกดยอมรับหรือปฏิเสธ',
 'line','normal','pending',jsonb_build_object('request_code',substr(v_id::text,1,12)),'owner_invitation_'||v_id::text);
 insert into public.audit_logs(family_id,actor_user_id,target_user_id,event_type,resource,new_data,description)
 values(p_family,p_actor,p_new_owner,'owner_transfer_requested','family_ownership',
 jsonb_build_object('request_id',v_id,'old_owner_role',p_old_role),'Owner transfer pending recipient acceptance');
 return v_id;
end;$function$

CREATE OR REPLACE FUNCTION private.phms_queue_person_linked_owner_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_person_id uuid;
 v_family_person_id uuid;
 v_linked_user_id uuid;
 v_recipient uuid;
 v_label text;
 v_roles text;
begin
 if new.event_type not in ('person_invite_direct_linked','person_claim_approved_and_linked','person_claim_confirmed') then
   return new;
 end if;
 if new.event_type='person_claim_confirmed' and coalesce(new.new_data->>'status','')<>'completed' then
   return new;
 end if;

 begin v_person_id:=nullif(new.new_data->>'person_id','')::uuid; exception when others then v_person_id:=null; end;
 if v_person_id is null and new.resource='persons' then v_person_id:=new.record_id; end if;
 if v_person_id is null or new.family_id is null then return new; end if;

 v_family_person_id:=new.family_person_id;
 if v_family_person_id is null then
   select fp.id into v_family_person_id
   from public.family_persons fp
   where fp.family_id=new.family_id and fp.person_id=v_person_id and coalesce(fp.status,'active')='active'
   limit 1;
 end if;

 select p.linked_user_id into v_linked_user_id from public.persons p where p.id=v_person_id;
 if v_linked_user_id is null then return new; end if;

 select string_agg(private.phms_role_thai(r.role),' • ' order by
   case r.role when 'owner' then 1 when 'admin' then 2 when 'caregiver' then 3 when 'patient' then 4 else 5 end)
 into v_roles
 from public.family_role_assignments r
 where r.family_id=new.family_id and r.user_id=v_linked_user_id and r.status='active';

 for v_recipient in
   select distinct fra.user_id
   from public.family_role_assignments fra
   where fra.family_id=new.family_id
     and fra.status='active'
     and fra.role in ('owner','admin')
     and fra.user_id is distinct from v_linked_user_id
 loop
   v_label:=coalesce(
     case when v_family_person_id is not null
       then private.family_person_label_for_viewer(v_recipient,v_family_person_id)
       else null end,
     (select nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),'') from public.persons p where p.id=v_person_id),
     'บุคคลในครอบครัว'
   );

   insert into public.notifications(
     family_id,recipient_user_id,event_type,title,message,related_record_id,
     channel,priority,status,person_id,family_person_id,
     scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
   ) values(
     new.family_id,v_recipient,'person_account_linked',
     '✅ มีการเชื่อมบัญชีกับบุคคล',
     v_label||E'\nเชื่อมบัญชีเรียบร้อย\nบทบาทหลังเชื่อม: '||coalesce(v_roles,'ผู้ป่วย'),
     v_person_id,'line','normal','pending',v_person_id,v_family_person_id,
     now(),now(),
     jsonb_build_object(
       'family_person_id',v_family_person_id,
       'person_id',v_person_id,
       'linked_user_id',v_linked_user_id,
       'roles',v_roles,
       'source_event',new.event_type
     ),
     'person-linked:'||new.id::text||':'||v_recipient::text,
     now(),now()
   )
   on conflict (dedupe_key) where dedupe_key is not null do nothing;
 end loop;

 return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_real_data_gate_decision(p_family_id uuid, p_person_id uuid, p_resources text[], p_operation text, p_actor_user_id uuid DEFAULT NULL::uuid, p_requested_records integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_global boolean:=false;
  v_pilot private.phms_real_data_pilot_families%rowtype;
  v_resource text;
  v_resources text[]:=array[]::text[];
  v_active_people integer:=0;
  v_record_count integer:=0;
  v_requested integer:=greatest(coalesce(p_requested_records,0),0);
  v_operation text:=lower(btrim(coalesce(p_operation,'')));
begin
  select coalesce(allow_real_data,false)
  into v_global
  from public.phms_runtime_environment
  where environment='production'
  limit 1;

  if coalesce(v_global,false) then
    return jsonb_build_object(
      'allowed',true,'mode','global',
      'reason','global_real_data_enabled'
    );
  end if;

  if p_family_id is null or p_person_id is null then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','pilot_family_context_required'
    );
  end if;

  select * into v_pilot
  from private.phms_real_data_pilot_families
  where family_id=p_family_id;

  if not found then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','family_not_in_real_data_pilot',
      'family_id',p_family_id
    );
  end if;

  if v_pilot.status<>'active' then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','pilot_not_active',
      'pilot_status',v_pilot.status
    );
  end if;

  if now()<v_pilot.starts_at
     or (v_pilot.ends_at is not null and now()>=v_pilot.ends_at) then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','pilot_outside_active_window',
      'starts_at',v_pilot.starts_at,
      'ends_at',v_pilot.ends_at
    );
  end if;

  if not exists(
    select 1 from public.families f
    where f.id=p_family_id and f.status='active'
  ) then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','pilot_family_inactive'
    );
  end if;

  if not exists(
    select 1
    from public.family_persons fp
    where fp.family_id=p_family_id
      and fp.person_id=p_person_id
      and fp.status='active'
  ) then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','person_not_active_in_pilot_family',
      'person_id',p_person_id
    );
  end if;

  if p_actor_user_id is not null
     and not exists(
       select 1
       from public.family_memberships fm
       where fm.family_id=p_family_id
         and fm.user_id=p_actor_user_id
         and fm.status='active'
     ) then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','actor_not_active_family_member'
    );
  end if;

  select count(*) into v_active_people
  from public.family_persons fp
  where fp.family_id=p_family_id and fp.status='active';

  if v_active_people>v_pilot.max_people then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','pilot_person_limit_exceeded',
      'active_people',v_active_people,
      'max_people',v_pilot.max_people
    );
  end if;

  foreach v_resource in array coalesce(p_resources,array[]::text[]) loop
    v_resource:=case lower(btrim(coalesce(v_resource,'')))
      when 'medications' then 'medication'
      when 'person_medications' then 'medication'
      when 'appointment' then 'appointment'
      when 'appointments' then 'appointment'
      when 'health_data' then 'health'
      when 'health_measurement' then 'health'
      when 'health_measurements' then 'health'
      when 'measurement' then 'health'
      when 'medical_document' then 'document'
      when 'medical_documents' then 'document'
      when 'documents' then 'document'
      else lower(btrim(coalesce(v_resource,'')))
    end;
    if v_resource<>'' and not (v_resource=any(v_resources)) then
      v_resources:=array_append(v_resources,v_resource);
    end if;
  end loop;

  if exists(
    select 1 from unnest(v_resources) r
    where not (r=any(v_pilot.allowed_resources))
  ) then
    return jsonb_build_object(
      'allowed',false,'mode','pilot',
      'reason','pilot_resource_not_allowed',
      'requested_resources',v_resources,
      'allowed_resources',v_pilot.allowed_resources
    );
  end if;

  if v_operation='commit' and not v_pilot.allow_intake_commit then
    return jsonb_build_object('allowed',false,'mode','pilot','reason','pilot_commit_disabled');
  elsif v_operation='update' and not v_pilot.allow_crud_update then
    return jsonb_build_object('allowed',false,'mode','pilot','reason','pilot_update_disabled');
  elsif v_operation in ('stop','delete') and not v_pilot.allow_crud_stop then
    return jsonb_build_object('allowed',false,'mode','pilot','reason','pilot_stop_disabled');
  elsif v_operation not in ('commit','update','stop','delete') then
    return jsonb_build_object('allowed',false,'mode','pilot','reason','invalid_pilot_operation');
  end if;

  if v_operation='commit' then
    select
      (select count(*)
       from public.person_medications pm
       join public.family_persons fp on fp.person_id=pm.person_id
       where fp.family_id=p_family_id
         and pm.created_at>=v_pilot.starts_at)
      +
      (select count(*)
       from public.appointments a
       join public.family_persons fp on fp.person_id=a.person_id
       where fp.family_id=p_family_id
         and a.created_at>=v_pilot.starts_at)
      +
      (select count(*)
       from public.health_measurements h
       join public.family_persons fp on fp.person_id=h.person_id
       where fp.family_id=p_family_id
         and h.created_at>=v_pilot.starts_at)
      +
      (select count(*)
       from public.medical_documents d
       join public.family_persons fp on fp.person_id=d.person_id
       where fp.family_id=p_family_id
         and d.created_at>=v_pilot.starts_at)
    into v_record_count;

    if v_record_count+v_requested>v_pilot.max_canonical_records then
      return jsonb_build_object(
        'allowed',false,'mode','pilot',
        'reason','pilot_record_limit_exceeded',
        'current_records',v_record_count,
        'requested_records',v_requested,
        'max_records',v_pilot.max_canonical_records
      );
    end if;
  end if;

  return jsonb_build_object(
    'allowed',true,
    'mode','pilot',
    'reason','pilot_scope_allowed',
    'family_id',p_family_id,
    'person_id',p_person_id,
    'resources',v_resources,
    'operation',v_operation,
    'active_people',v_active_people,
    'max_people',v_pilot.max_people,
    'current_records',case when v_operation='commit' then v_record_count else null end,
    'requested_records',case when v_operation='commit' then v_requested else null end,
    'max_records',v_pilot.max_canonical_records,
    'ends_at',v_pilot.ends_at
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_reconcile_intake_candidate_core(p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_c public.data_intake_candidates%rowtype;
  v_s public.data_intake_sources%rowtype;
  v_ds public.data_intake_sessions%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_target_person uuid;
  v_family_person_person uuid;
  v_blocking jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_match_count integer := 0;
  v_other record;
  v_ts timestamptz;
  v_med_id uuid;
  v_norm_key text;
  v_measurement_type text;
  v_value_numeric numeric;
  v_systolic numeric;
  v_diastolic numeric;
  v_selected jsonb := null;
begin
  select * into v_c
  from public.data_intake_candidates
  where id=p_candidate_id
  for update;
  if not found then
    return jsonb_build_object('ok',false,'error','candidate_not_found');
  end if;

  select * into v_s
  from public.data_intake_sources
  where id=v_c.source_id;
  if not found then
    return jsonb_build_object('ok',false,'error','source_not_found');
  end if;

  select * into v_ds
  from public.data_intake_sessions
  where id=v_c.session_id;
  if not found then
    return jsonb_build_object('ok',false,'error','session_not_found');
  end if;

  v_target_person := coalesce(v_c.person_id,v_ds.person_id);

  if v_s.storage_asset_id is not null then
    select * into v_asset
    from public.phms_storage_assets
    where id=v_s.storage_asset_id;
  end if;

  -- Recompute links from scratch. History remains in intake actions.
  delete from public.data_intake_reconciliation_links
  where candidate_id=v_c.id;

  -- Deterministic Person consistency checks.
  if v_c.person_id is not null
     and v_ds.person_id is not null
     and v_c.person_id <> v_ds.person_id then
    v_blocking := v_blocking || jsonb_build_array('person_mismatch_candidate_session');
  end if;

  if v_ds.family_person_id is not null then
    select fp.person_id into v_family_person_person
    from public.family_persons fp
    where fp.id=v_ds.family_person_id;

    if v_family_person_person is not null
       and v_target_person is not null
       and v_family_person_person <> v_target_person then
      v_blocking := v_blocking || jsonb_build_array('person_mismatch_family_context');
    end if;
  end if;

  if v_asset.id is not null
     and v_asset.person_id is not null
     and v_target_person is not null
     and v_asset.person_id <> v_target_person then
    v_blocking := v_blocking || jsonb_build_array('person_mismatch_storage_asset');
    insert into public.data_intake_reconciliation_links(
      candidate_id,match_type,target_table,target_record_id,score,reasons,selected
    ) values(
      v_c.id,'conflict','phms_storage_assets',v_asset.id,1.0,
      jsonb_build_array('storage_asset_person_differs_from_intake_person'),false
    );
    v_match_count := v_match_count + 1;
  end if;

  -- Same logical storage asset reused by another non-final intake.
  for v_other in
    select os.id source_id, ods.id session_id, ods.person_id,
           os.storage_asset_id
    from public.data_intake_sources os
    join public.data_intake_sessions ods on ods.id=os.session_id
    where os.storage_asset_id=v_s.storage_asset_id
      and os.id<>v_s.id
      and ods.status not in ('cancelled','rejected')
  loop
    if v_target_person is not null
       and v_other.person_id is not null
       and v_other.person_id<>v_target_person then
      v_blocking := v_blocking || jsonb_build_array('person_mismatch_duplicate_file');
      insert into public.data_intake_reconciliation_links(
        candidate_id,match_type,target_table,target_record_id,score,reasons,selected
      ) values(
        v_c.id,'conflict','data_intake_sources',v_other.source_id,1.0,
        jsonb_build_array('same_storage_asset','different_person'),false
      );
    else
      v_blocking := v_blocking || jsonb_build_array('duplicate_file');
      insert into public.data_intake_reconciliation_links(
        candidate_id,match_type,target_table,target_record_id,score,reasons,selected
      ) values(
        v_c.id,'exact','data_intake_sources',v_other.source_id,1.0,
        jsonb_build_array('same_storage_asset'),true
      );
      if v_selected is null then
        v_selected := jsonb_build_object('target_table','data_intake_sources','target_record_id',v_other.source_id,'score',1.0);
      end if;
    end if;
    v_match_count := v_match_count + 1;
  end loop;

  -- Exact file bytes by SHA-256, including different object paths.
  if v_asset.checksum_sha256 is not null then
    for v_other in
      select
        oa.id asset_id,
        coalesce(oa.person_id,ods.person_id) resolved_person_id
      from public.phms_storage_assets oa
      left join public.data_intake_sources os on os.storage_asset_id=oa.id
      left join public.data_intake_sessions ods on ods.id=os.session_id
      where oa.checksum_sha256=v_asset.checksum_sha256
        and oa.id<>v_asset.id
        and oa.deleted_at is null
        and (ods.id is null or ods.status not in ('cancelled','rejected'))
      group by oa.id,coalesce(oa.person_id,ods.person_id)
    loop
      if v_target_person is not null
         and v_other.resolved_person_id is not null
         and v_other.resolved_person_id<>v_target_person then
        v_blocking := v_blocking || jsonb_build_array('person_mismatch_sha256');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'conflict','phms_storage_assets',v_other.asset_id,1.0,
          jsonb_build_array('same_sha256','different_person'),false
        );
      else
        v_blocking := v_blocking || jsonb_build_array('duplicate_file_sha256');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'exact','phms_storage_assets',v_other.asset_id,1.0,
          jsonb_build_array('same_sha256'),false
        );
      end if;
      v_match_count := v_match_count + 1;
    end loop;

    -- Exact duplicate of a canonical medical document.
    for v_other in
      select md.id,md.person_id
      from public.medical_documents md
      where lower(md.checksum_sha256)=lower(v_asset.checksum_sha256)
        and md.deleted_at is null
    loop
      if v_target_person is not null and v_other.person_id<>v_target_person then
        v_blocking := v_blocking || jsonb_build_array('person_mismatch_canonical_document');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'conflict','medical_documents',v_other.id,1.0,
          jsonb_build_array('same_sha256','canonical_document','different_person'),false
        );
      else
        v_blocking := v_blocking || jsonb_build_array('duplicate_document');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'exact','medical_documents',v_other.id,1.0,
          jsonb_build_array('same_sha256','canonical_document'),true
        );
        if v_selected is null then
          v_selected := jsonb_build_object('target_table','medical_documents','target_record_id',v_other.id,'score',1.0);
        end if;
      end if;
      v_match_count := v_match_count + 1;
    end loop;
  end if;

  -- Exact semantic duplicate among intake candidates.
  if v_c.fingerprint_sha256 is not null and v_target_person is not null then
    for v_other in
      select oc.id
      from public.data_intake_candidates oc
      join public.data_intake_sessions ods on ods.id=oc.session_id
      where oc.id<>v_c.id
        and oc.person_id=v_target_person
        and oc.candidate_type=v_c.candidate_type
        and oc.fingerprint_sha256=v_c.fingerprint_sha256
        and oc.review_status not in ('rejected')
        and ods.status not in ('cancelled','rejected')
    loop
      v_blocking := v_blocking || jsonb_build_array('duplicate_record_candidate');
      insert into public.data_intake_reconciliation_links(
        candidate_id,match_type,target_table,target_record_id,score,reasons,selected
      ) values(
        v_c.id,'exact','data_intake_candidates',v_other.id,1.0,
        jsonb_build_array('same_person','same_candidate_type','same_fingerprint'),true
      );
      if v_selected is null then
        v_selected := jsonb_build_object('target_table','data_intake_candidates','target_record_id',v_other.id,'score',1.0);
      end if;
      v_match_count := v_match_count + 1;
    end loop;
  end if;

  -- Canonical appointment duplicate.
  if v_c.candidate_type='appointment' and v_target_person is not null then
    if coalesce(v_c.normalized_data->>'external_reference','')<>'' then
      for v_other in
        select a.id
        from public.appointments a
        where a.person_id=v_target_person
          and a.deleted_at is null
          and a.external_reference=v_c.normalized_data->>'external_reference'
      loop
        v_blocking := v_blocking || jsonb_build_array('duplicate_record_appointment');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'exact','appointments',v_other.id,1.0,
          jsonb_build_array('same_person','same_external_reference'),true
        );
        v_match_count := v_match_count + 1;
      end loop;
    end if;

    v_ts := private.phms_try_timestamptz(v_c.normalized_data->>'appointment_at');
    if v_ts is not null then
      for v_other in
        select a.id
        from public.appointments a
        where a.person_id=v_target_person
          and a.deleted_at is null
          and abs(extract(epoch from (a.appointment_at-v_ts))) <= 300
          and (
            (coalesce(v_c.normalized_data->>'hospital_name','')<>'' and
             private.phms_normalize_dedupe_text(a.hospital_name)=private.phms_normalize_dedupe_text(v_c.normalized_data->>'hospital_name'))
            or
            (coalesce(v_c.normalized_data->>'department','')<>'' and
             private.phms_normalize_dedupe_text(a.department)=private.phms_normalize_dedupe_text(v_c.normalized_data->>'department'))
            or
            (coalesce(v_c.normalized_data->>'doctor_name','')<>'' and
             private.phms_normalize_dedupe_text(a.doctor_name)=private.phms_normalize_dedupe_text(v_c.normalized_data->>'doctor_name'))
            or
            (coalesce(v_c.normalized_data->>'title','')<>'' and
             private.phms_normalize_dedupe_text(a.title)=private.phms_normalize_dedupe_text(v_c.normalized_data->>'title'))
          )
      loop
        v_blocking := v_blocking || jsonb_build_array('duplicate_record_appointment_probable');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'probable','appointments',v_other.id,0.92,
          jsonb_build_array('same_person','appointment_time_within_5_minutes','matching_appointment_context'),false
        );
        v_match_count := v_match_count + 1;
      end loop;
    end if;
  end if;

  -- Canonical active medication duplicate.
  if v_c.candidate_type='medication' and v_target_person is not null then
    v_med_id := private.phms_try_uuid(v_c.normalized_data->>'medication_id');
    v_norm_key := nullif(private.phms_normalize_dedupe_text(v_c.normalized_data->>'normalized_key'),'');

    if v_med_id is not null then
      for v_other in
        select pm.id
        from public.person_medications pm
        where pm.person_id=v_target_person
          and pm.medication_id=v_med_id
          and pm.deleted_at is null
          and pm.status not in ('discontinued','completed')
      loop
        v_blocking := v_blocking || jsonb_build_array('duplicate_record_medication');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'exact','person_medications',v_other.id,1.0,
          jsonb_build_array('same_person','same_medication_id','active_medication'),true
        );
        v_match_count := v_match_count + 1;
      end loop;
    elsif v_norm_key is not null then
      for v_other in
        select pm.id
        from public.person_medications pm
        join public.medication_master mm on mm.id=pm.medication_id
        where pm.person_id=v_target_person
          and pm.deleted_at is null
          and pm.status not in ('discontinued','completed')
          and private.phms_normalize_dedupe_text(mm.normalized_key)=v_norm_key
      loop
        v_blocking := v_blocking || jsonb_build_array('duplicate_record_medication_probable');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'probable','person_medications',v_other.id,0.90,
          jsonb_build_array('same_person','same_normalized_medication_key','active_medication'),false
        );
        v_match_count := v_match_count + 1;
      end loop;
    end if;
  end if;

  -- Canonical health measurement duplicate.
  if v_c.candidate_type in ('health_measurement','measurement')
     and v_target_person is not null then
    v_ts := private.phms_try_timestamptz(v_c.normalized_data->>'measured_at');
    v_measurement_type := nullif(private.phms_normalize_dedupe_text(v_c.normalized_data->>'measurement_type'),'');
    v_value_numeric := private.phms_try_numeric(v_c.normalized_data->>'value_numeric');
    v_systolic := private.phms_try_numeric(v_c.normalized_data->>'systolic');
    v_diastolic := private.phms_try_numeric(v_c.normalized_data->>'diastolic');

    if v_ts is not null and v_measurement_type is not null then
      for v_other in
        select hm.id
        from public.health_measurements hm
        where hm.person_id=v_target_person
          and hm.deleted_at is null
          and private.phms_normalize_dedupe_text(hm.measurement_type)=v_measurement_type
          and abs(extract(epoch from (hm.measured_at-v_ts))) <= 60
          and (
            (v_value_numeric is not null and hm.value_numeric=v_value_numeric)
            or
            (v_systolic is not null and v_diastolic is not null
             and hm.systolic=v_systolic and hm.diastolic=v_diastolic)
            or
            (coalesce(v_c.normalized_data->>'value_text','')<>'' and
             private.phms_normalize_dedupe_text(hm.value_text)=private.phms_normalize_dedupe_text(v_c.normalized_data->>'value_text'))
          )
      loop
        v_blocking := v_blocking || jsonb_build_array('duplicate_record_measurement');
        insert into public.data_intake_reconciliation_links(
          candidate_id,match_type,target_table,target_record_id,score,reasons,selected
        ) values(
          v_c.id,'exact','health_measurements',v_other.id,1.0,
          jsonb_build_array('same_person','same_measurement','time_within_60_seconds'),true
        );
        v_match_count := v_match_count + 1;
      end loop;
    end if;
  end if;

  -- Deduplicate conflict codes for clean UX/API.
  select coalesce(jsonb_agg(x order by x::text),'[]'::jsonb)
  into v_blocking
  from (
    select distinct x
    from jsonb_array_elements(v_blocking) x
  ) d;

  select coalesce(jsonb_agg(x order by x::text),'[]'::jsonb)
  into v_warnings
  from (
    select distinct x
    from jsonb_array_elements(v_warnings) x
  ) d;

  update public.data_intake_candidates
  set conflict_data=jsonb_build_object(
        'blocking_conflicts',v_blocking,
        'warnings',v_warnings,
        'duplicate_detected',exists(
          select 1 from jsonb_array_elements_text(v_blocking) x
          where x like 'duplicate%'
        ),
        'person_mismatch',exists(
          select 1 from jsonb_array_elements_text(v_blocking) x
          where x like 'person_mismatch%'
        ),
        'checked_at',now()
      ),
      reconciliation_data=jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_sha256',v_c.fingerprint_sha256,
        'match_count',v_match_count,
        'selected_match',v_selected,
        'checked_at',now()
      )),
      review_status=case
        when jsonb_array_length(v_blocking)>0
             and review_status not in ('rejected','committed')
          then 'needs_review'
        else review_status
      end,
      updated_at=now()
  where id=v_c.id;

  insert into public.data_intake_actions(
    session_id,candidate_id,actor_user_id,action,after_data,reason
  )
  values(
    v_c.session_id,v_c.id,v_s.submitted_by,'reconcile',
    jsonb_build_object(
      'blocking_conflicts',v_blocking,
      'warnings',v_warnings,
      'match_count',v_match_count,
      'fingerprint_sha256',v_c.fingerprint_sha256
    ),
    case when jsonb_array_length(v_blocking)>0 then 'duplicate_or_person_conflict_detected' else 'no_conflict' end
  );

  return jsonb_build_object(
    'ok',jsonb_array_length(v_blocking)=0,
    'candidate_id',v_c.id,
    'fingerprint_sha256',v_c.fingerprint_sha256,
    'blocking_conflicts',v_blocking,
    'warnings',v_warnings,
    'match_count',v_match_count,
    'selected_match',v_selected
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_recycle_capture_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_fp record;
  v_family_id uuid;
  v_family_person_id uuid;
  v_person_id uuid;
  v_resource text;
  v_action text;
  v_capture boolean:=false;
  v_snapshot jsonb;
begin
  begin
    v_actor:=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid;
  exception when others then v_actor:=null;
  end;

  if tg_table_name='appointments' then
    v_person_id:=new.person_id;
    v_family_id:=new.family_id;
    v_family_person_id:=new.family_person_id;
    v_resource:='appointment';
    if old.deleted_at is null and new.deleted_at is not null then
      v_action:='soft_delete'; v_capture:=true;
    elsif coalesce(old.status,'')<>'cancelled' and new.status='cancelled' then
      v_action:='cancel'; v_capture:=true;
    end if;

    if v_capture then
      if v_family_person_id is null and v_family_id is not null then
        select fp.id into v_family_person_id
        from public.family_persons fp
        where fp.family_id=v_family_id and fp.person_id=v_person_id and coalesce(fp.status,'active')='active'
        limit 1;
      end if;
      if v_family_id is not null then
        perform private.phms_put_recycle_entry(
          v_family_id,v_family_person_id,v_person_id,v_resource,new.id,v_action,
          to_jsonb(old),coalesce(new.cancel_reason,'appointment changed to recoverable state'),v_actor
        );
      end if;
    end if;
    return new;
  end if;

  if tg_table_name='person_medications' then
    v_resource:='medication';
    v_person_id:=new.person_id;
    if old.deleted_at is null and new.deleted_at is not null then
      v_action:='soft_delete'; v_capture:=true;
    elsif coalesce(old.status,'')<>'discontinued' and new.status='discontinued' then
      v_action:='stop'; v_capture:=true;
    end if;
    if v_capture then
      select to_jsonb(old)||jsonb_build_object(
        '_regimens',coalesce((
          select jsonb_agg(to_jsonb(r) order by r.created_at,r.id)
          from public.medication_regimens r
          where r.person_medication_id=old.id and r.deleted_at is null
        ),'[]'::jsonb)
      ) into v_snapshot;
    end if;

  elsif tg_table_name='health_measurements' then
    v_resource:='health';
    v_person_id:=new.person_id;
    v_action:='soft_delete';
    v_capture:=old.deleted_at is null and new.deleted_at is not null;
    v_snapshot:=to_jsonb(old);
  elsif tg_table_name='medical_documents' then
    v_resource:='document';
    v_person_id:=new.person_id;
    v_action:='soft_delete';
    v_capture:=old.deleted_at is null and new.deleted_at is not null;
    v_snapshot:=to_jsonb(old);
  elsif tg_table_name='phms_storage_assets' then
    v_resource:='storage_asset';
    v_person_id:=new.person_id;
    v_action:='soft_delete';
    v_capture:=(old.deleted_at is null and new.deleted_at is not null)
      or (coalesce(old.lifecycle_state,'')<>'deleted' and new.lifecycle_state='deleted');
    v_snapshot:=to_jsonb(old);
  end if;

  if v_capture and v_person_id is not null then
    if v_snapshot is null then v_snapshot:=to_jsonb(old); end if;
    for v_fp in
      select fp.family_id,fp.id family_person_id
      from public.family_persons fp
      where fp.person_id=v_person_id and coalesce(fp.status,'active')='active'
    loop
      perform private.phms_put_recycle_entry(
        v_fp.family_id,v_fp.family_person_id,v_person_id,v_resource,new.id,
        coalesce(v_action,'soft_delete'),v_snapshot,
        tg_table_name||' moved to recycle bin',v_actor
      );
    end loop;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_schedule_appointment_assignee_ack(p_assignee_id uuid, p_requested_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ass public.appointment_assignees%rowtype;
  v_appt public.appointments%rowtype;
  v_ack_id uuid;
  v_notification_id uuid;
  v_schedule timestamptz;
  v_name text;
  v_role_label text;
begin
  select * into v_ass
  from public.appointment_assignees
  where id=p_assignee_id and status<>'removed';
  if not found then raise exception 'appointment_assignee_not_found'; end if;

  select * into v_appt
  from public.appointments
  where id=v_ass.appointment_id and deleted_at is null;
  if not found then raise exception 'appointment_not_found'; end if;

  if v_ass.user_id is null then
    update public.appointment_assignees
    set status='assigned',
        requires_ack=false,
        acknowledged_at=null,
        updated_at=now()
    where id=v_ass.id;

    return jsonb_build_object(
      'ok',true,
      'require_ack',false,
      'status','assigned',
      'line_unlinked',true,
      'assignment_notification_suppressed',true
    );
  end if;

  update public.notifications n
  set status='cancelled',updated_at=now(),last_error='assignment_ack_replaced'
  where n.id in (
    select ak.notification_id
    from public.appointment_acknowledgements ak
    where ak.appointment_id=v_ass.appointment_id
      and ak.user_id=v_ass.user_id
      and ak.ack_type='assignment'
      and ak.status='pending'
      and private.phms_try_uuid(ak.change_snapshot->>'assignee_id')=v_ass.id
      and ak.notification_id is not null
  )
  and n.status in ('pending','failed');

  update public.appointment_acknowledgements ak
  set status='expired',updated_at=now()
  where ak.appointment_id=v_ass.appointment_id
    and ak.user_id=v_ass.user_id
    and ak.ack_type='assignment'
    and ak.status='pending'
    and private.phms_try_uuid(ak.change_snapshot->>'assignee_id')=v_ass.id;

  if v_appt.appointment_at < now() then
    update public.appointment_assignees
    set status='assigned',
        requires_ack=false,
        acknowledged_at=null,
        updated_at=now()
    where id=v_ass.id;

    return jsonb_build_object(
      'ok',true,
      'require_ack',false,
      'status','assigned',
      'historical_appointment',true,
      'assignment_notification_suppressed',true
    );
  end if;

  if v_ass.user_id=p_requested_by or v_appt.assignee_ack_days_before is null then
    update public.appointment_assignees
    set status='accepted',
        requires_ack=false,
        acknowledged_at=case when user_id=p_requested_by then coalesce(acknowledged_at,now()) else acknowledged_at end,
        updated_at=now()
    where id=v_ass.id;
    return jsonb_build_object('ok',true,'require_ack',false,'status','accepted');
  end if;

  if v_appt.status<>'confirmed' then
    update public.appointment_assignees
    set status='assigned',requires_ack=true,acknowledged_at=null,updated_at=now()
    where id=v_ass.id;
    return jsonb_build_object(
      'ok',true,'require_ack',true,'status','assigned',
      'deferred_until_appointment_confirmed',true
    );
  end if;

  v_schedule:=greatest(
    now(),
    coalesce(v_appt.appointment_at-make_interval(days=>v_appt.assignee_ack_days_before),now())
  );

  v_name:=case
    when v_ass.family_person_id is not null then
      private.family_person_label_for_viewer(p_requested_by,v_ass.family_person_id)
    else
      private.family_user_label_for_viewer(
        p_requested_by,v_appt.family_id,v_ass.user_id
      )
  end;

  v_role_label:=case v_ass.assignment_role
    when 'driver' then 'คนขับรถ / คนพาไป'
    when 'caregiver' then 'ผู้ดูแลวันนัด'
    when 'companion' then 'คนไปด้วย'
    when 'booker' then 'คนประสานงานนัด'
    when 'responsible' then 'ผู้รับผิดชอบหลัก'
    else 'ผู้รับผิดชอบ'
  end;

  insert into public.appointment_acknowledgements(
    appointment_id,user_id,ack_type,status,requested_by,requested_at,
    change_snapshot,created_at,updated_at
  )
  values(
    v_ass.appointment_id,v_ass.user_id,'assignment','pending',p_requested_by,now(),
    jsonb_build_object(
      'assignee_id',v_ass.id,'role',v_ass.assignment_role,
      'appointment_at',v_appt.appointment_at,'days_before',v_appt.assignee_ack_days_before
    ),now(),now()
  )
  returning id into v_ack_id;

  insert into public.notifications(
    family_id,recipient_user_id,person_id,family_person_id,
    event_type,title,message,related_record_id,channel,priority,status,
    scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
  )
  values(
    v_appt.family_id,v_ass.user_id,v_appt.person_id,v_appt.family_person_id,
    'appointment_assignment','📅 มีหน้าที่ในวันนัด',
    concat(
      '👤 ',coalesce(v_name,'ผู้ใช้'),
      E'\nหน้าที่: ',v_role_label,
      E'\nนัดเพื่อ: ',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
      E'\nวันเวลา: ',to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),
      E'\n\nกรุณากด “รับทราบ” เพื่อยืนยันว่าคุณเห็นหน้าที่นี้แล้ว'
    ),
    v_appt.id,'line','high','pending',v_schedule,v_schedule,
    jsonb_build_object(
      'appointment_id',v_appt.id,'appointment_code',substr(v_appt.id::text,1,12),
      'ack_id',v_ack_id,'ack_code',substr(v_ack_id::text,1,12),
      'require_ack',true,'ack_type','assignment','assignment_role',v_ass.assignment_role
    ),
    'appointment_assignment:'||v_ack_id::text,now(),now()
  )
  returning id into v_notification_id;

  update public.appointment_acknowledgements
  set notification_id=v_notification_id,updated_at=now()
  where id=v_ack_id;

  update public.appointment_assignees
  set status='assigned',requires_ack=true,acknowledged_at=null,updated_at=now()
  where id=v_ass.id;

  return jsonb_build_object(
    'ok',true,'require_ack',true,'status','assigned',
    'ack_code',substr(v_ack_id::text,1,12),'scheduled_for',v_schedule
  );
end
$function$

CREATE OR REPLACE FUNCTION private.phms_stamp_line_link_completion_for_user(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_person_id uuid;
  v_count integer := 0;
  v_row record;
begin
  if p_user_id is null then
    return 0;
  end if;

  select p.id into v_person_id
  from public.persons p
  where p.linked_user_id = p_user_id
    and coalesce(p.status,'active') = 'active'
  limit 1;

  if v_person_id is null then
    return 0;
  end if;

  for v_row in
    update public.line_identities li
       set linking_completed_at = now(),
           updated_at = now()
     where li.user_id = p_user_id
       and coalesce(li.is_active,false) = true
       and li.linking_completed_at is null
     returning li.id, li.linking_completed_at
  loop
    v_count := v_count + 1;
    insert into public.audit_logs(
      actor_user_id,target_user_id,event_type,resource,record_id,new_data,description
    ) values (
      p_user_id,p_user_id,'line_linking_completed','line_identity',v_row.id,
      jsonb_build_object('line_identity_id',v_row.id,'person_id',v_person_id,'linking_completed_at',v_row.linking_completed_at),
      'LINE identity, PHMS user account, and self person linkage completed.'
    );
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.phms_storage_asset_visible_to_actor(p_asset_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_asset public.phms_storage_assets%rowtype; v_has_docs boolean:=false; v_resource text;
begin
 if v_uid is null then return false;end if;
 select * into v_asset from public.phms_storage_assets where id=p_asset_id and deleted_at is null;
 if not found then return false;end if;
 select exists(select 1 from public.medical_documents md where md.storage_asset_id=p_asset_id and md.deleted_at is null)
 or exists(select 1 from public.appointment_document_links adl where adl.storage_asset_id=p_asset_id or exists(select 1 from public.medical_documents md where md.id=adl.medical_document_id and md.storage_asset_id=p_asset_id))
 into v_has_docs;
 if v_has_docs then
  if exists(select 1 from public.medical_documents md where md.storage_asset_id=p_asset_id and md.deleted_at is null
    and not exists(select 1 from public.family_persons fp where fp.person_id=md.person_id and private.user_can_access_family_person(v_uid,fp.id,'documents','view'))) then return false;end if;
  if exists(select 1 from public.appointment_document_links adl join public.appointments ap on ap.id=adl.appointment_id
    where (adl.storage_asset_id=p_asset_id or exists(select 1 from public.medical_documents md where md.id=adl.medical_document_id and md.storage_asset_id=p_asset_id))
    and not exists(select 1 from public.family_persons fp where fp.person_id=ap.person_id and private.user_can_access_family_person(v_uid,fp.id,'documents','view'))) then return false;end if;
  if exists(select 1 from public.appointment_document_links adl join public.appointments ap on ap.id=adl.appointment_id
    where (adl.storage_asset_id=p_asset_id or exists(select 1 from public.medical_documents md where md.id=adl.medical_document_id and md.storage_asset_id=p_asset_id))
    and adl.link_kind in ('receipt','payment_slip','payment_qr','payment_other')
    and not exists(select 1 from public.family_persons fp where fp.person_id=ap.person_id and private.user_can_access_family_person(v_uid,fp.id,'expenses','view'))) then return false;end if;
  return exists(select 1 from public.medical_documents md join public.family_persons fp on fp.person_id=md.person_id where md.storage_asset_id=p_asset_id and md.deleted_at is null and private.user_can_access_family_person(v_uid,fp.id,'documents','view'))
    or exists(select 1 from public.appointment_document_links adl join public.appointments ap on ap.id=adl.appointment_id join public.family_persons fp on fp.person_id=ap.person_id
       where (adl.storage_asset_id=p_asset_id or exists(select 1 from public.medical_documents md where md.id=adl.medical_document_id and md.storage_asset_id=p_asset_id)) and private.user_can_access_family_person(v_uid,fp.id,'documents','view'));
 end if;
 if v_asset.person_id is null then return v_asset.created_by=v_uid;end if;
 v_resource:=case v_asset.permission_resource when 'health' then 'health_data' when 'document' then 'documents' else v_asset.permission_resource end;
 return exists(select 1 from public.family_persons fp where fp.person_id=v_asset.person_id and private.user_can_access_family_person(v_uid,fp.id,v_resource,'view'));
end $function$

CREATE OR REPLACE FUNCTION private.phms_sync_appointment_followup_link_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_a uuid;
  v_b uuid;
begin
  if new.followup_of_appointment_id is null
     or new.id = new.followup_of_appointment_id then
    return new;
  end if;

  if new.id < new.followup_of_appointment_id then
    v_a := new.id;
    v_b := new.followup_of_appointment_id;
  else
    v_a := new.followup_of_appointment_id;
    v_b := new.id;
  end if;

  insert into private.appointment_links(
    appointment_id_a, appointment_id_b, link_kind, source, created_by
  )
  values(v_a, v_b, 'continuity', 'primary_followup_sync', new.created_by)
  on conflict do nothing;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_sync_appointment_preparation_tasks()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_raw text:=private.phms_clean_appointment_preparation_text(new.preparation_notes);
  v_item text;
  v_items text[];
  v_key text;
begin
  -- Auto tasks are a checklist projection of preparation_notes only.
  -- Do not infer multiple tasks from keywords; that produced false positives
  -- such as "ไม่ต้องงดน้ำ" becoming a fasting task.
  update public.appointment_tasks
  set status='cancelled',updated_at=now()
  where appointment_id=new.id
    and (
      source_key like 'auto:list:%'
      or source_key in ('auto:lab','auto:imaging','auto:urine','auto:fasting','auto:document')
    )
    and status='pending';

  if nullif(btrim(coalesce(v_raw,'')),'') is null then
    return new;
  end if;

  select array_agg(
           btrim(regexp_replace(line,'^([0-9]{1,2}[.)]|[-•☐☑✅⬜])[[:space:]]*','','i'))
           order by ord
         )
  into v_items
  from regexp_split_to_table(v_raw,E'\n+') with ordinality as x(line,ord)
  where nullif(
    btrim(regexp_replace(line,'^([0-9]{1,2}[.)]|[-•☐☑✅⬜])[[:space:]]*','','i')),
    ''
  ) is not null;

  foreach v_item in array v_items loop
    v_key:='auto:list:'||
      substr(encode(extensions.digest(lower(v_item),'sha256'),'hex'),1,20);

    insert into public.appointment_tasks(
      appointment_id,task_type,title,instruction,source_key,created_by
    ) values(
      new.id,
      private.phms_appointment_task_type_from_text(v_item),
      v_item,
      null,
      v_key,
      new.created_by
    )
    on conflict (appointment_id,source_key) where source_key is not null
    do update set
      title=excluded.title,
      task_type=excluded.task_type,
      instruction=null,
      status=case
        when public.appointment_tasks.status='cancelled' then 'pending'
        else public.appointment_tasks.status
      end,
      updated_at=now();
  end loop;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_sync_line_identity_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_account_id uuid;
  v_primary_user_id uuid;
begin
  if new.account_id is null and new.user_id is not null then
    v_account_id := private.phms_ensure_account_for_user(new.user_id, 'legacy_line_anchor');
    new.account_id := v_account_id;
  elsif new.account_id is not null then
    select a.primary_auth_user_id
    into v_primary_user_id
    from public.accounts a
    where a.id = new.account_id;

    if v_primary_user_id is null then
      raise exception 'account_not_found';
    end if;

    -- user_id is now a compatibility pointer to the account's primary auth anchor.
    new.user_id := v_primary_user_id;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_sync_person_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_account_id uuid;
  v_primary_user_id uuid;
begin
  if new.linked_account_id is null and new.linked_user_id is not null then
    v_account_id := private.phms_ensure_account_for_user(new.linked_user_id, 'login');
    new.linked_account_id := v_account_id;
  elsif new.linked_account_id is not null then
    select a.primary_auth_user_id
    into v_primary_user_id
    from public.accounts a
    where a.id = new.linked_account_id;

    if v_primary_user_id is null then
      raise exception 'account_not_found';
    end if;

    new.linked_user_id := v_primary_user_id;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_sync_person_hospital_hn(p_person_id uuid, p_organization_id uuid, p_hospital_name text, p_hn text, p_actor_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_hn text:=nullif(btrim(coalesce(p_hn,'')),'');
  v_issuer text;
  v_org uuid;
  v_code text;
  v_norm text;
  v_id uuid;
begin
  if p_person_id is null or v_hn is null then return null; end if;

  v_org:=coalesce(
    p_organization_id,
    private.phms_canonical_hospital_org_id(p_hospital_name)
  );

  if v_org is not null then
    select private.phms_canonical_hospital_display(
      coalesce(nullif(btrim(o.external_code),''),concat_ws(' ',o.name,o.branch_name))
    )
    into v_issuer
    from public.healthcare_organizations o
    where o.id=v_org and o.deleted_at is null;
  end if;

  v_issuer:=coalesce(
    v_issuer,
    private.phms_canonical_hospital_display(p_hospital_name)
  );
  if v_issuer is null then return null; end if;

  v_code:=private.phms_canonical_hospital_code(v_issuer);
  v_norm:=lower(regexp_replace(v_issuer,'[^0-9a-zก-๙]+','','g'));

  select pi.id into v_id
  from public.person_identifiers pi
  where pi.person_id=p_person_id
    and pi.identifier_type='hospital_hn'
    and (
      (v_org is not null and pi.issuer_organization_id=v_org)
      or (v_code is not null and private.phms_canonical_hospital_code(pi.issuer)=v_code)
      or (
        v_org is null and v_code is null
        and lower(regexp_replace(coalesce(pi.issuer,''),'[^0-9a-zก-๙]+','','g'))=v_norm
      )
    )
  order by
    case when v_org is not null and pi.issuer_organization_id=v_org then 0 else 1 end,
    pi.updated_at desc nulls last,
    pi.created_at desc
  limit 1;

  if v_id is null then
    insert into public.person_identifiers(
      person_id,identifier_type,identifier_value,issuer,
      issuer_organization_id,is_primary,is_verified,verified_by,verified_at,
      created_at,updated_at
    ) values(
      p_person_id,'hospital_hn',v_hn,v_issuer,
      v_org,false,false,null,null,now(),now()
    )
    returning id into v_id;
  else
    update public.person_identifiers
    set identifier_value=v_hn,
        issuer=v_issuer,
        issuer_organization_id=coalesce(v_org,issuer_organization_id),
        is_verified=false,
        verified_by=null,
        verified_at=null,
        updated_at=now()
    where id=v_id;
  end if;

  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_sync_person_hospital_vn(p_person_id uuid, p_organization_id uuid, p_hospital_name text, p_vn text, p_actor_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
