begin
  if p_person_id is null or v_vn is null then return null; end if;

  v_org:=coalesce(p_organization_id,private.phms_canonical_hospital_org_id(p_hospital_name));

  if v_org is not null then
    select private.phms_canonical_hospital_display(
      coalesce(nullif(btrim(o.external_code),''),concat_ws(' ',o.name,o.branch_name))
    )
