  if v_issuer is null then return null; end if;

  v_code:=private.phms_canonical_hospital_code(v_issuer);
  v_norm:=lower(regexp_replace(v_issuer,'[^0-9a-zก-๙]+','','g'));

  select pi.id into v_id
  from public.person_identifiers pi
  where pi.person_id=p_person_id
    and pi.identifier_type='hospital_vn'
    and (
      (v_org is not null and pi.issuer_organization_id=v_org)
      or (
        v_org is null and v_code is not null
        and private.phms_canonical_hospital_code(pi.issuer)=v_code
      )
      or (
        v_org is null and v_code is null
        and lower(regexp_replace(coalesce(pi.issuer,''),'[^0-9a-zก-๙]+','','g'))=v_norm
      )
    )
  order by
    case when v_org is not null and pi.issuer_organization_id=v_org then 0 else 1 end,
    pi.updated_at desc nulls last,
    pi.created_at desc
  limit 1;

  if v_id is null then
    insert into public.person_identifiers(
      person_id,identifier_type,identifier_value,issuer,
      issuer_organization_id,is_primary,is_verified,verified_by,verified_at,
