        issuer=v_issuer,
        issuer_organization_id=coalesce(v_org,issuer_organization_id),
        is_primary=true,
        is_verified=false,
        verified_by=null,
        verified_at=null,
        updated_at=now()
    where id=v_id;
  end if;

  if v_org is not null then
    delete from public.person_identifiers pi
    where pi.person_id=p_person_id
      and pi.identifier_type='hospital_vn'
      and pi.issuer_organization_id=v_org
      and pi.id<>v_id;
  end if;

  return v_id;
end
