CREATE OR REPLACE FUNCTION private.phms_sync_recurring_care_plan_from_appointment(p_appointment_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_a public.appointments%rowtype;
  v_plan_type text;
  v_care_item text;
  v_interval integer;
  v_due date;
  v_plan_id uuid;
  v_status text;
  v_due_source text;
begin
  select * into v_a
  from public.appointments
  where id=p_appointment_id
    and deleted_at is null;

  if not found then
    return jsonb_build_object('ok',false,'reason','appointment_not_found');
  end if;

  if v_a.family_id is null then
    return jsonb_build_object('ok',true,'synced',false,'reason','family_required_for_plan');
  end if;

  if v_a.appointment_type='follow_up' and v_a.followup_kind='chronic_routine' then
    v_plan_type:='chronic_followup';
    v_interval:=v_a.followup_interval_months;
    v_care_item:=coalesce(
      nullif(btrim(v_a.care_topic),''),
      nullif(btrim(v_a.title),''),
      'ติดตามโรคประจำตัว'
    );
  elsif v_a.appointment_type='checkup' then
    v_plan_type:='routine_checkup';
    v_interval:=v_a.preventive_interval_months;
    v_care_item:=coalesce(
      nullif(btrim(v_a.care_topic),''),
      nullif(btrim(v_a.title),''),
      'ตรวจสุขภาพตามรอบ'
    );
  elsif v_a.appointment_type='vaccination' then
    v_plan_type:='vaccination';
    v_interval:=v_a.preventive_interval_months;
    v_care_item:=coalesce(
      nullif(btrim(v_a.care_topic),''),
      nullif(btrim(v_a.title),''),
      'ฉีดวัคซีนตามรอบ'
    );
  else
    return jsonb_build_object('ok',true,'synced',false,'reason','not_recurring_care');
  end if;

  if v_interval is not null and v_interval between 1 and 120 and v_a.appointment_at is not null then
    v_due:=(
      (v_a.appointment_at at time zone 'Asia/Bangkok')::date
      + make_interval(months=>v_interval)
    )::date;
    v_status:='active';
    v_due_source:='clinician_advised';
  else
    v_due:=null;
    v_status:='draft';
    v_due_source:='not_confirmed';
  end if;

  select p.id into v_plan_id
  from public.preventive_care_plans p
  where p.person_id=v_a.person_id
    and p.plan_type=v_plan_type
    and lower(btrim(p.care_item))=lower(btrim(v_care_item))
    and p.deleted_at is null
    and p.status in ('draft','active','paused')
  order by p.updated_at desc, p.created_at desc
  limit 1
  for update;

  if v_plan_id is null then
    insert into public.preventive_care_plans(
      family_id,person_id,plan_type,care_item,
      interval_value,interval_unit,next_due_on,due_source,
      next_step,remind_days_before,reminders_enabled,
      source_appointment_id,status,created_by,updated_by
    )
    values(
      v_a.family_id,v_a.person_id,v_plan_type,v_care_item,
      v_interval,case when v_interval is null then null else 'months' end,
      v_due,v_due_source,
      'remind_to_book',14,false,
      v_a.id,v_status,p_actor_user_id,p_actor_user_id
    )
    returning id into v_plan_id;
  else
    update public.preventive_care_plans
    set family_id=v_a.family_id,
        interval_value=v_interval,
        interval_unit=case when v_interval is null then null else 'months' end,
        next_due_on=v_due,
        due_source=v_due_source,
        source_appointment_id=v_a.id,
        status=case when status='paused' then 'paused' else v_status end,
        updated_by=p_actor_user_id,
        updated_at=now()
    where id=v_plan_id;
  end if;

  return jsonb_build_object(
    'ok',true,
    'synced',true,
    'plan_id',v_plan_id,
    'plan_type',v_plan_type,
    'status',v_status,
    'interval_months',v_interval,
    'next_due_on',v_due,
    'reminders_enabled',false
  );
end
$function$

