CREATE OR REPLACE FUNCTION private.phms_validate_appointment_candidate_required_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_errors jsonb;
begin
  if new.candidate_type<>'appointment' then
    return new;
  end if;

  v_errors:=coalesce(new.validation_data->'blocking_errors','[]'::jsonb);
  if jsonb_typeof(v_errors)<>'array' then
    v_errors:='[]'::jsonb;
  end if;

  if private.phms_try_timestamptz(new.normalized_data->>'appointment_at') is null then
    if not (v_errors ? 'appointment_at_required') then
      v_errors:=v_errors||jsonb_build_array('appointment_at_required');
    end if;
  else
    select coalesce(jsonb_agg(x),'[]'::jsonb)
    into v_errors
    from jsonb_array_elements(v_errors) x
    where x <> to_jsonb('appointment_at_required'::text);
  end if;

  new.validation_data:=coalesce(new.validation_data,'{}'::jsonb)
    || jsonb_build_object('blocking_errors',v_errors);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.phms_write_intake_provenance(p_candidate_id uuid, p_resource_type text, p_record_id uuid, p_actor_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_c public.data_intake_candidates%rowtype;
  v_s public.data_intake_sources%rowtype;
  v_id uuid;
  v_conf numeric;
  v_method text;
  v_text text;
begin
  select * into v_c from public.data_intake_candidates where id=p_candidate_id;
  if not found then raise exception 'candidate_not_found'; end if;

  if v_c.source_id is not null then
    select * into v_s from public.data_intake_sources where id=v_c.source_id;
  end if;

  v_conf := private.phms_try_numeric(
    coalesce(
      v_c.confidence_data->>'quality_score',
      v_c.confidence_data->>'ocr_confidence',
      v_c.confidence_data->>'classification_confidence'
    )
  );
  if v_conf is not null and v_conf>1 then v_conf:=v_conf/100; end if;
  if v_conf is not null then v_conf:=greatest(0,least(1,v_conf)); end if;

  v_method := coalesce(
    nullif(v_c.confidence_data->>'provider',''),
    nullif(v_s.source_metadata->>'extraction_provider',''),
    'confirmed_intake'
  );

  v_text := left(
    coalesce(
      v_c.normalized_data->>'source_text',
      v_c.extracted_data->>'source_text',
      v_s.raw_text,
      ''
    ),
    4000
  );

  insert into public.record_provenance(
    person_id,resource_type,record_id,
    source_type,source_document_id,source_record_id,
    source_text,confidence,extraction_method,
    verified_by,verified_at,source_storage_asset_id
  )
  values(
    v_c.person_id,p_resource_type,p_record_id,
    'intake_candidate',v_s.source_document_id,v_c.id,
    nullif(v_text,''),v_conf,v_method,
    p_actor_user_id,now(),v_s.storage_asset_id
  )
  on conflict (source_record_id,resource_type)
    where source_type='intake_candidate' and source_record_id is not null
  do update set
    record_id=excluded.record_id,
    person_id=excluded.person_id,
    source_document_id=excluded.source_document_id,
    source_text=excluded.source_text,
    confidence=excluded.confidence,
    extraction_method=excluded.extraction_method,
    verified_by=excluded.verified_by,
    verified_at=excluded.verified_at,
    source_storage_asset_id=excluded.source_storage_asset_id
  returning id into v_id;

  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION private.queue_line_rich_menu_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'net'
AS $function$
declare
  v_secret text;
  v_url text := 'https://buxvdlfrikpwdscdlcfd.supabase.co/functions/v1/line-richmenu-sync';
begin
  if new.line_user_id is null or btrim(new.line_user_id)='' then
