CREATE OR REPLACE FUNCTION private.resolve_line_account_for_service(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, account_id uuid, user_id uuid, onboarding_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_account_id uuid;
  v_primary_user_id uuid;
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then
    raise exception 'line_user_id_required';
  end if;

  select li.*
  into v_line
  from public.line_identities li
  where li.line_user_id = p_line_user_id
    and li.is_active = true
  order by li.updated_at desc nulls last, li.created_at desc, li.id desc
  limit 1;

  if not found then
    raise exception 'active_line_identity_required';
  end if;

  v_account_id := v_line.account_id;

  -- Compatibility repair for any legacy writer that populated user_id only.
  if v_account_id is null and v_line.user_id is not null then
    v_account_id := private.phms_ensure_account_for_user(v_line.user_id, 'legacy_line_anchor');

    update public.line_identities
    set account_id = v_account_id,
        updated_at = now()
    where id = v_line.id;
  end if;

  if v_account_id is null then
    raise exception 'line_identity_not_linked';
  end if;

  select a.primary_auth_user_id
  into v_primary_user_id
  from public.accounts a
  where a.id = v_account_id
    and a.status = 'active';

  if v_primary_user_id is null then
    raise exception 'account_not_active';
  end if;

  return query
  select v_line.id, v_account_id, v_primary_user_id, v_line.onboarding_status;
end
$function$

CREATE OR REPLACE FUNCTION private.resolve_line_family_member(p_line_user_id text, p_member_code text)
 RETURNS TABLE(line_identity_id uuid, actor_user_id uuid, family_id uuid, target_user_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_target uuid;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(
    v_line.line_identity_id,
    v_line.user_id
  );

  select c.* into v_ctx
  from private.line_identity_contexts c
  where c.line_identity_id=v_line.line_identity_id;

  if not found
     or v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;

  if not exists(
    select 1
    from public.family_memberships fm
    where fm.family_id=v_ctx.active_family_id
      and fm.user_id=v_line.user_id
      and fm.status='active'
  ) then
    raise exception 'family_context_not_accessible';
  end if;

  select fm.user_id into v_target
  from public.family_memberships fm
  where fm.family_id=v_ctx.active_family_id
    and fm.status='active'
    and substr(
      encode(
        digest(
          fm.user_id::text||':'||
          v_line.line_identity_id::text||':'||
          v_ctx.active_family_id::text,
          'sha256'
        ),
        'hex'
      ),
      1,12
    )=lower(btrim(p_member_code))
  limit 1;

  if v_target is null then
    raise exception 'family_member_not_found';
  end if;

  return query
  select
    v_line.line_identity_id,
    v_line.user_id,
    v_ctx.active_family_id,
    v_target;
end
$function$

CREATE OR REPLACE FUNCTION private.resolve_line_family_person_code(p_line_user_id text, p_person_code text)
 RETURNS TABLE(line_identity_id uuid, actor_user_id uuid, family_id uuid, family_person_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp uuid;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select c.* into v_ctx
  from private.line_identity_contexts c
  where c.line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;

  if not exists(
    select 1 from public.family_memberships fm
    where fm.family_id=v_ctx.active_family_id
      and fm.user_id=v_line.user_id
      and fm.status='active'
  ) then
    raise exception 'family_context_not_accessible';
  end if;

  select fp.id into v_fp
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_ctx.active_family_id
    and coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
    and substr(
      encode(digest(fp.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),
      1,12
    )=lower(btrim(p_person_code))
  limit 1;

  if v_fp is null then raise exception 'family_person_not_found'; end if;

  if not (
    private.family_person_is_visible_to_user(v_line.user_id,v_fp)
    or private.can_manage_family_person_setup(v_line.user_id,v_fp)
    or private.can_manage_family_person_visibility(v_line.user_id,v_fp)
  ) then
    raise exception 'family_person_not_found';
  end if;

  return query
  select v_line.line_identity_id,v_line.user_id,v_ctx.active_family_id,v_fp;
end
$function$

CREATE OR REPLACE FUNCTION private.resolve_line_identity_command_context(p_line_identity_id uuid, p_user_id uuid, p_resource text DEFAULT NULL::text, p_action text DEFAULT 'view'::text, p_require_person boolean DEFAULT false, p_required_scope text DEFAULT 'any'::text)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, target_person_id uuid, target_person_name text, family_name text, context_valid boolean, context_ready boolean, permission_checked boolean, permission_granted boolean, resolution_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_ctx private.line_identity_contexts%rowtype; v_self public.persons%rowtype; v_family public.families%rowtype; v_fp public.family_persons%rowtype; v_person public.persons%rowtype;
 v_resource text:=nullif(btrim(p_resource),''); v_action text:=lower(coalesce(nullif(btrim(p_action),''),'view')); v_required_scope text:=lower(coalesce(nullif(btrim(p_required_scope),''),'any'));
 v_owner boolean:=false; v_family_perm boolean:=false; v_person_perm boolean:=false; v_permission_checked boolean:=false; v_permission_granted boolean:=true;
begin
 if p_user_id is null or p_line_identity_id is null then raise exception 'line_context_identity_required'; end if;
 if v_action not in ('view','create','update','delete','manage_permissions','receive_notifications') then raise exception 'unsupported_permission_action'; end if;
 if v_required_scope not in ('any','personal','family') then raise exception 'unsupported_required_scope'; end if;
 perform private.ensure_line_identity_context(p_line_identity_id,p_user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=p_line_identity_id;
 if v_required_scope<>'any' and v_ctx.active_scope<>v_required_scope then
  return query select p_user_id,v_ctx.active_scope,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,null::text,false,false,false,false,
   case when v_required_scope='family' then 'family_scope_required' else 'personal_scope_required' end::text; return;
 end if;
 if v_ctx.active_scope='personal' then
  select * into v_self from public.persons where linked_user_id=p_user_id order by case when coalesce(status,'active')='active' then 0 else 1 end,created_at,id limit 1;
  if v_self.id is null then return query select p_user_id,'personal'::text,null::uuid,null::uuid,null::uuid,null::text,null::text,(not p_require_person),false,false,true,case when p_require_person then 'personal_person_required' else 'personal_person_missing' end::text; return; end if;
  if coalesce(v_self.status,'active')<>'active' then return query select p_user_id,'personal'::text,null::uuid,null::uuid,v_self.id,coalesce(nullif(btrim(v_self.display_name),''),nullif(btrim(concat_ws(' ',v_self.first_name,v_self.last_name)),''),null),null::text,false,false,false,false,'personal_person_inactive'::text; return; end if;
  return query select p_user_id,'personal'::text,null::uuid,null::uuid,v_self.id,coalesce(nullif(btrim(v_self.display_name),''),nullif(btrim(concat_ws(' ',v_self.first_name,v_self.last_name)),''),null),null::text,true,true,false,true,'ok'::text; return;
 end if;
 if v_ctx.active_family_id is null then return query select p_user_id,'family'::text,null::uuid,v_ctx.active_family_person_id,null::uuid,null::text,null::text,false,false,false,false,'family_required'::text; return; end if;
 select * into v_family from public.families where id=v_ctx.active_family_id;
 if not found or coalesce(v_family.status,'active')<>'active' or not exists(select 1 from public.family_memberships fm where fm.user_id=p_user_id and fm.family_id=v_ctx.active_family_id and fm.status='active') then
  return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,v_family.family_name,false,false,false,false,'family_membership_inactive'::text; return;
 end if;
 if v_ctx.active_family_person_id is not null then
  select * into v_fp from public.family_persons where id=v_ctx.active_family_person_id and family_id=v_ctx.active_family_id;
  if not found or coalesce(v_fp.status,'active')<>'active' or not private.user_can_see_family_person(p_user_id,v_fp.id) then
   return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,v_family.family_name,false,false,false,false,'family_person_not_accessible'::text; return;
  end if;
  select * into v_person from public.persons where id=v_fp.person_id;
  if not found or coalesce(v_person.status,'active')<>'active' then
   return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,v_fp.person_id,null::text,v_family.family_name,false,false,false,false,'person_inactive'::text; return;
  end if;
 elsif p_require_person then
  return query select p_user_id,'family'::text,v_ctx.active_family_id,null::uuid,null::uuid,null::text,v_family.family_name,true,false,false,false,'family_person_required'::text; return;
 end if;
 if v_resource is not null then
  v_permission_checked:=true;
  select exists(select 1 from public.family_role_assignments r where r.user_id=p_user_id and r.family_id=v_ctx.active_family_id and r.role='owner' and r.status='active') into v_owner;
  if v_action='receive_notifications' then
   if v_ctx.active_family_person_id is null then v_permission_granted:=false;
   else select exists(select 1 from public.person_permissions pp where pp.user_id=p_user_id and pp.family_id=v_ctx.active_family_id and pp.family_person_id=v_ctx.active_family_person_id and pp.resource=v_resource and pp.status='active' and pp.can_receive_notifications) into v_person_perm;
   v_permission_granted:=v_owner or v_person_perm; end if;
  else
   select exists(select 1 from public.family_permissions fp where fp.user_id=p_user_id and fp.family_id=v_ctx.active_family_id and fp.resource=v_resource and case v_action when 'view' then fp.can_view when 'create' then fp.can_create when 'update' then fp.can_update when 'delete' then fp.can_delete when 'manage_permissions' then fp.can_manage_permissions else false end) into v_family_perm;
   if v_ctx.active_family_person_id is not null and v_action in ('view','create','update','delete') then
    select exists(select 1 from public.person_permissions pp where pp.user_id=p_user_id and pp.family_id=v_ctx.active_family_id and pp.family_person_id=v_ctx.active_family_person_id and pp.resource=v_resource and pp.status='active' and case v_action when 'view' then pp.can_view when 'create' then pp.can_create when 'update' then pp.can_update when 'delete' then pp.can_delete else false end) into v_person_perm;
   end if;
   v_permission_granted:=v_owner or v_family_perm or v_person_perm;
  end if;
 end if;
 return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,v_person.id,
  case when v_person.id is null then null else private.family_person_label_for_viewer(p_user_id,v_ctx.active_family_person_id) end,
  v_family.family_name,true,(not p_require_person or v_person.id is not null),v_permission_checked,v_permission_granted,
  case when v_permission_checked and not v_permission_granted then 'permission_denied' else 'ok' end::text;
end $function$

CREATE OR REPLACE FUNCTION private.resolve_user_command_context(p_user_id uuid, p_resource text DEFAULT NULL::text, p_action text DEFAULT 'view'::text, p_require_person boolean DEFAULT false, p_required_scope text DEFAULT 'any'::text)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, target_person_id uuid, target_person_name text, family_name text, context_valid boolean, context_ready boolean, permission_checked boolean, permission_granted boolean, resolution_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ctx public.user_contexts%rowtype; v_self public.persons%rowtype; v_family public.families%rowtype; v_fp public.family_persons%rowtype; v_person public.persons%rowtype;
  v_resource text:=nullif(btrim(p_resource),''); v_action text:=lower(coalesce(nullif(btrim(p_action),''),'view')); v_required_scope text:=lower(coalesce(nullif(btrim(p_required_scope),''),'any'));
  v_owner boolean:=false; v_family_perm boolean:=false; v_person_perm boolean:=false; v_permission_checked boolean:=false; v_permission_granted boolean:=true;
begin
  if p_user_id is null then raise exception 'user_id_required'; end if;
  if v_action not in ('view','create','update','delete','manage_permissions','receive_notifications') then raise exception 'unsupported_permission_action'; end if;
  if v_required_scope not in ('any','personal','family') then raise exception 'unsupported_required_scope'; end if;
  insert into public.user_contexts(user_id,active_scope,active_family_id,active_family_person_id,context_changed_at)
  values(p_user_id,'personal',null,null,now()) on conflict on constraint user_contexts_pkey do nothing;
  select uc.* into v_ctx from public.user_contexts uc where uc.user_id=p_user_id;

  if v_required_scope<>'any' and v_ctx.active_scope<>v_required_scope then
    return query select p_user_id,v_ctx.active_scope,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,null::text,false,false,false,false,
      case when v_required_scope='family' then 'family_scope_required' else 'personal_scope_required' end::text; return;
  end if;
  if v_ctx.active_scope='personal' then
    select p.* into v_self from public.persons p where p.linked_user_id=p_user_id order by case when coalesce(p.status,'active')='active' then 0 else 1 end,p.created_at,p.id limit 1;
    if v_self.id is null then return query select p_user_id,'personal'::text,null::uuid,null::uuid,null::uuid,null::text,null::text,(not p_require_person),false,false,true,case when p_require_person then 'personal_person_required' else 'personal_person_missing' end::text; return; end if;
    if coalesce(v_self.status,'active')<>'active' then return query select p_user_id,'personal'::text,null::uuid,null::uuid,v_self.id,coalesce(nullif(btrim(v_self.display_name),''),nullif(btrim(concat_ws(' ',v_self.first_name,v_self.last_name)),''),null),null::text,false,false,false,false,'personal_person_inactive'::text; return; end if;
    return query select p_user_id,'personal'::text,null::uuid,null::uuid,v_self.id,coalesce(nullif(btrim(v_self.display_name),''),nullif(btrim(concat_ws(' ',v_self.first_name,v_self.last_name)),''),null),null::text,true,true,false,true,'ok'::text; return;
  end if;

  if v_ctx.active_scope<>'family' then return query select p_user_id,v_ctx.active_scope,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,null::text,false,false,false,false,'invalid_scope'::text; return; end if;
  if v_ctx.active_family_id is null then return query select p_user_id,'family'::text,null::uuid,v_ctx.active_family_person_id,null::uuid,null::text,null::text,false,false,false,false,'family_required'::text; return; end if;
  select f.* into v_family from public.families f where f.id=v_ctx.active_family_id;
  if v_family.id is null then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,null::text,false,false,false,false,'family_not_found'::text; return; end if;
  if coalesce(v_family.status,'active')<>'active' then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,v_family.family_name,false,false,false,false,'family_inactive'::text; return; end if;
  if not exists(select 1 from public.family_memberships fm where fm.user_id=p_user_id and fm.family_id=v_ctx.active_family_id and fm.status='active') then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,v_family.family_name,false,false,false,false,'family_membership_inactive'::text; return; end if;

  if v_ctx.active_family_person_id is not null then
    select fp.* into v_fp from public.family_persons fp where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id;
    if v_fp.id is null then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,null::uuid,null::text,v_family.family_name,false,false,false,false,'family_person_not_found'::text; return; end if;
    if coalesce(v_fp.status,'active')<>'active' then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,v_fp.person_id,null::text,v_family.family_name,false,false,false,false,'family_person_inactive'::text; return; end if;
    select p.* into v_person from public.persons p where p.id=v_fp.person_id;
    if v_person.id is null then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,v_fp.person_id,null::text,v_family.family_name,false,false,false,false,'person_not_found'::text; return; end if;
    if coalesce(v_person.status,'active')<>'active' then return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,v_person.id,private.family_person_label_for_viewer(p_user_id,v_fp.id),v_family.family_name,false,false,false,false,'person_inactive'::text; return; end if;
  elsif p_require_person then
    return query select p_user_id,'family'::text,v_ctx.active_family_id,null::uuid,null::uuid,null::text,v_family.family_name,true,false,false,false,'family_person_required'::text; return;
  end if;

  if v_resource is not null then
    v_permission_checked:=true;
    select exists(select 1 from public.family_role_assignments fra where fra.user_id=p_user_id and fra.family_id=v_ctx.active_family_id and fra.role='owner' and fra.status='active') into v_owner;
    if v_action='receive_notifications' then
      if v_ctx.active_family_person_id is null then v_permission_granted:=false;
      else select exists(select 1 from public.person_permissions pp where pp.user_id=p_user_id and pp.family_id=v_ctx.active_family_id and pp.family_person_id=v_ctx.active_family_person_id and pp.resource=v_resource and pp.status='active' and pp.can_receive_notifications=true) into v_person_perm; v_permission_granted:=v_owner or v_person_perm; end if;
    else
      select exists(select 1 from public.family_permissions fp where fp.user_id=p_user_id and fp.family_id=v_ctx.active_family_id and fp.resource=v_resource and case v_action when 'view' then coalesce(fp.can_view,false) when 'create' then coalesce(fp.can_create,false) when 'update' then coalesce(fp.can_update,false) when 'delete' then coalesce(fp.can_delete,false) when 'manage_permissions' then coalesce(fp.can_manage_permissions,false) else false end) into v_family_perm;
      if v_ctx.active_family_person_id is not null and v_action in ('view','create','update','delete') then select exists(select 1 from public.person_permissions pp where pp.user_id=p_user_id and pp.family_id=v_ctx.active_family_id and pp.family_person_id=v_ctx.active_family_person_id and pp.resource=v_resource and pp.status='active' and case v_action when 'view' then coalesce(pp.can_view,false) when 'create' then coalesce(pp.can_create,false) when 'update' then coalesce(pp.can_update,false) when 'delete' then coalesce(pp.can_delete,false) else false end) into v_person_perm; end if;
      v_permission_granted:=v_owner or v_family_perm or v_person_perm;
    end if;
  end if;

  return query select p_user_id,'family'::text,v_ctx.active_family_id,v_ctx.active_family_person_id,v_person.id,
    case when v_person.id is null then null else private.family_person_label_for_viewer(p_user_id,v_ctx.active_family_person_id) end,
    v_family.family_name,true,(not p_require_person or v_person.id is not null),v_permission_checked,v_permission_granted,
    case when v_permission_checked and not v_permission_granted then 'permission_denied' else 'ok' end::text;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_notification_preference_to_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_fp uuid;
  v_uid uuid;
  v_res text;
begin
  v_fp:=coalesce(new.family_person_id,old.family_person_id);
  v_uid:=coalesce(new.user_id,old.user_id);
  v_res:=coalesce(new.resource,old.resource);

  update public.person_permissions pp
  set updated_at=now()
  where pp.family_person_id=v_fp
    and pp.user_id=v_uid
    and pp.resource=v_res
    and pp.status='active';

  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_sync_link_completion_from_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
begin
  if new.user_id is not null and coalesce(new.is_active,false)=true then
    perform private.phms_stamp_line_link_completion_for_user(new.user_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.user_can_access_family_person(p_user_id uuid, p_family_person_id uuid, p_resource text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_resource text:=case lower(btrim(coalesce(p_resource,'')))
  when 'profile' then 'persons' when 'health' then 'health_data'
  when 'document' then 'documents' when 'expense' then 'expenses'
  when 'medication' then 'medications' else lower(btrim(coalesce(p_resource,''))) end;
 v_action text:=lower(btrim(coalesce(p_action,'view')));
begin
 if p_user_id is null or p_family_person_id is null then return false; end if;
 if v_action='receive_notifications' then
   return private.person_notification_enabled(p_user_id,p_family_person_id,v_resource);
 end if;
 if v_action not in ('view','create','update','delete') then return false; end if;
 if v_resource not in ('persons','medications','appointments','health_data','emergency','documents','expenses') then return false; end if;
 if v_resource='persons' and exists (select 1 from public.person_permissions pp where pp.family_person_id=p_family_person_id and pp.user_id=p_user_id and pp.resource='persons' and pp.status='active') then
 return exists(select 1 from public.person_permissions pp join public.family_persons fp on fp.id=pp.family_person_id and fp.status='active' join public.family_memberships fm on fm.family_id=fp.family_id and fm.user_id=pp.user_id and fm.status='active'
 where pp.family_person_id=p_family_person_id and pp.user_id=p_user_id and pp.resource='persons' and pp.status='active'
 and case v_action when 'view' then coalesce(pp.can_view,false) when 'create' then coalesce(pp.can_create,false) when 'update' then coalesce(pp.can_update,false) when 'delete' then coalesce(pp.can_delete,false) else false end);
 end if;
 if v_resource in ('persons','appointments','medications','health_data','documents','expenses')
    and exists(select 1 from public.person_five_category_policies pol where pol.family_person_id=p_family_person_id and pol.user_id=p_user_id)
 then
   return exists(
    select 1 from public.person_five_category_policies pol
    join public.family_persons fp on fp.id=pol.family_person_id and fp.family_id=pol.family_id and fp.status='active'
    join public.persons pe on pe.id=fp.person_id and pe.status='active'
    join public.family_memberships fm on fm.family_id=fp.family_id and fm.user_id=pol.user_id and fm.status='active'
    where pol.family_person_id=p_family_person_id and pol.user_id=p_user_id
      and private.phms_five_category_level_allows(pol.base_level,pol.overrides,v_resource,v_action)
   );
 end if;

 if v_resource in ('documents','expenses') and exists (select 1 from public.family_persons fp join public.family_memberships fm on fm.family_id=fp.family_id and fm.user_id=p_user_id and fm.status='active' where fp.id=p_family_person_id and coalesce(fp.status,'active')='active'
    and exists(select 1 from public.persons p where p.id=fp.person_id and coalesce(p.status,'active')='active')) is not true then return false; end if;
 if v_resource in ('documents','expenses') and exists (select 1 from public.person_permissions px where px.family_person_id=p_family_person_id and px.user_id=p_user_id and px.status='active' and px.resource=v_resource) then return exists(select 1 from public.person_permissions px where px.family_person_id=p_family_person_id and px.user_id=p_user_id and px.status='active' and px.resource=v_resource and case v_action when 'view' then coalesce(px.can_view,false) when 'create' then coalesce(px.can_create,false) when 'update' then coalesce(px.can_update,false) when 'delete' then coalesce(px.can_delete,false) else false end); end if;

 return exists(
  select 1 from public.family_persons fp
  where fp.id=p_family_person_id and coalesce(fp.status,'active')='active'
    and exists(select 1 from public.family_memberships fm
               where fm.family_id=fp.family_id and fm.user_id=p_user_id and fm.status='active')
    and (
      private.can_manage_family_person_setup(p_user_id,fp.id)
      or private.self_person_access_allowed(p_user_id,fp.id,v_resource,v_action)
      or (
        private.phms_is_medical_primary(p_user_id,fp.id)
        and not (v_resource='persons' and v_action in ('create','delete'))
      )
      or private.caregiver_assignment_allows(p_user_id,fp.id,v_resource,v_action)
      or (v_resource in ('documents','expenses') and exists(
        select 1 from public.family_permissions y
        where y.family_id=fp.family_id and y.user_id=p_user_id and y.resource=v_resource
          and case v_action when 'view' then coalesce(y.can_view,false)
            when 'create' then coalesce(y.can_create,false)
            when 'update' then coalesce(y.can_update,false)
            when 'delete' then coalesce(y.can_delete,false) else false end
      ))
      or exists(
        select 1 from public.person_permissions x
        where x.family_id=fp.family_id and x.family_person_id=fp.id
          and x.user_id=p_user_id and x.status='active' and x.resource=v_resource
          and case v_action
            when 'view' then coalesce(x.can_view,false)
            when 'create' then coalesce(x.can_create,false)
            when 'update' then coalesce(x.can_update,false)
            when 'delete' then coalesce(x.can_delete,false)
            else false end
      )
      or (
        v_resource='persons' and v_action='view'
        and (
          private.phms_is_medical_primary(p_user_id,fp.id)
          or exists(select 1 from public.person_caregiver_assignments ca
                    where ca.family_person_id=fp.id and ca.caregiver_user_id=p_user_id and ca.status='active'
                      and (ca.can_edit_profile or ca.can_manage_medications or ca.can_manage_appointments
                           or ca.can_manage_health or ca.can_manage_emergency))
          or exists(select 1 from public.person_permissions x
                    where x.family_id=fp.family_id and x.family_person_id=fp.id and x.user_id=p_user_id
                      and x.status='active' and x.resource in ('persons','medications','appointments','health_data','emergency')
                      and (coalesce(x.can_view,false) or coalesce(x.can_create,false)
                           or coalesce(x.can_update,false) or coalesce(x.can_delete,false)))
        )
      )
    )
 );
end;
$function$
